    /// Stream-path activation pull from a peer: asks `node` to activate up to
    /// `max_jobs` of `job_type` on *its own* partitions for `worker`, returning the
    /// projected jobs. The peer leases them under `timeout`, so at-least-once is
    /// preserved by the owner's lock (if this gateway dies before the worker
    /// completes, the lease expires and the job re-activates on the owner). Empty on
    /// any error — the dispatcher simply moves on. Drives job aggregation: a worker
    /// attached to one gateway draws jobs from every node's partitions.
    #[allow(clippy::too_many_arguments)]
    pub(crate) async fn activate_from_peer(
        &self,
        node: u32,
        job_type: &str,
        worker: &str,
        max_jobs: usize,
        timeout: u64,
        fetch_variable: Option<&[String]>,
        with_lease: bool,
    ) -> Vec<models::ActivatedJobResult> {
        let link = match self.peer_link(node).await {
            Ok(l) => l,
            Err(_) => return Vec::new(),
        };
        let res = link
            .activate_jobs(
                job_type.to_string(),
                worker.to_string(),
                max_jobs as i64,
                timeout,
                fetch_variable.map(|f| f.to_vec()),
                with_lease,
            )
            .await;
        match res {
            Ok(r) if is_ok_status(r.status) => {
                let body = match r.body {
                    Some(b) => b,
                    None => return Vec::new(),
                };
                // Tolerant parse: the current wire shape is
                // `{ jobs: [...], backlog: N }`; fall back to a bare jobs array for
                // safety. The piggybacked backlog feeds Stage 2 fairness weighting.
                if let Some(backlog) = body.get("backlog").and_then(|v| v.as_i64()) {
                    crate::falcon::record_peer_backlog(node, backlog);
                }
                let jobs_val = body.get("jobs").cloned().unwrap_or(body);
                serde_json::from_value::<Vec<models::ActivatedJobResult>>(jobs_val)
                    .unwrap_or_default()
            }
            _ => Vec::new(),
        }
    }

    /// Forwards a job-retries update to the peer owning the job.
    #[cfg(any(feature = "console", test))]
    async fn forward_update_job_retries(
        &self,
        node: u32,
        job_key: u64,
        lease_token: Option<String>,
        retries: i32,
        operation_reference: Option<i64>,
    ) -> Result<(), (u16, String)> {
        let link = self.peer_link(node).await?;
        match link
            .update_job_retries(
                job_key.to_string(),
                lease_token,
                retries,
                operation_reference,
            )
            .await
        {
            Ok(r) if is_ok_status(r.status) => Ok(()),
            Ok(r) if r.status == 404 => Err((404, peer_detail(&r))),
            Ok(r) if r.status == 409 => Err((409, peer_detail(&r))),
            // Preserve the owner's retryable 503 (handoff pause / leadership
            // race) so callers can map it to Out::Unavailable instead of a
            // non-retryable 500 during the incident-resolution retry phase.
            Ok(r) if r.status == 503 => Err((503, peer_detail(&r))),
            Ok(r) => Err((500, peer_detail(&r))),
            Err(e) => Err((502, e.to_string())),
        }
    }

    /// Peer-side handler for a forwarded `createProcessInstance`: creates on one
    /// of THIS node's own partitions (never re-forwarding) and returns the full
    /// `CreateProcessInstanceResult` as JSON, so the originating gateway can map
    /// it straight back to its REST response. Mirrors the local REST create
    /// core + finalize. Backpressure/admission are applied at the receiving
    /// gateway, not here.
    #[allow(clippy::too_many_arguments)]
    pub(crate) async fn create_forwarded(
        &self,
        by_id: Option<String>,
        by_key: Option<String>,
        variables: std::collections::HashMap<String, Value>,
        tags: Vec<String>,
        business_id: Option<String>,
        await_completion: bool,
        fetch_variables: Option<Vec<String>>,
        request_timeout: Option<i64>,
        origin_protocol: &str,
    ) -> Result<serde_json::Value, (u16, String)> {
        // Placement protection (ADR 0014): a node that is saturated sheds the
        // forwarded create back to the ingress node (503 with the placement-shed
        // marker) so ingress can reroute it to an owner with headroom, instead of
        // being overrun by work placed on it. This closes the gap where forwarded
        // creates bypassed the owner's own admission gates. Off by default.
        if self.placement_mode.protects()
            && let Some(reason) = self.create_should_shed()
        {
            return Err((503, format!("{PLACEMENT_SHED_MARKER} {reason}")));
        }
        // ADR-0020 Tier-1: a forwarded create is still subject to the owner node's
        // global engine-saturation guard (the shared write path is this node's).
        if let Some(message) = self.tier1_should_shed() {
            return Err((503, message));
        }
        // ADR-0020 Tier-2: a forwarded create is still subject to the target
        // definition's per-definition latency budget on the owner node.
        if let Some(message) = self.tier2_should_shed(by_id.as_deref(), by_key.as_deref()) {
            return Err((503, message));
        }
        let tags_for_response = tags.clone();
        let business_id_for_response = business_id.clone();
        type CreateOk = (String, i32, String, u64, bool, Vec<Event>, Commit);
        // Under Raft, a forwarded create must be REPLICATED through this node's
        // Raft log, not applied directly to the local engine — otherwise the
        // instance would not survive this node's failure. Route it through the
        // shared Raft create core (durability is awaited inside the propose, so
        // the returned commit is already ready).
        let outcome: Result<CreateOk, (u16, String)> = if !self.raft.is_empty() {
            self.raft_create_core(by_id, by_key, None, variables, tags, business_id)
                .await
                .map(
                    |(
                        process_id,
                        version,
                        definition_key,
                        instance_key,
                        sync_completed,
                        routable,
                    )| {
                        (
                            process_id,
                            version,
                            definition_key,
                            instance_key,
                            sync_completed,
                            routable,
                            Commit::ready(),
                        )
                    },
                )
        } else {
            let payload_bytes = engine_vars_bytes(&variables);
            let _processing = ProcessingGuard::enter(&self.processing);
            let _bytes = ByteGuard::enter(&self.pipeline_bytes, payload_bytes);
            self.engine
                .for_create()
                .with_low(move |engine| {
                    let (process_id, sel_key, sel_ver) =
                        match resolve_create_selector(engine.state(), by_id, by_key, None) {
                            Ok(t) => t,
                            Err(e) => return Err(e),
                        };
                    match apply_create_instance_direct(
                        engine,
                        Command::create_instance_versioned(
                            process_id.clone(),
                            variables,
                            tags,
                            business_id,
                            sel_key,
                            sel_ver,
                        ),
                        &process_id,
                    ) {
                        Ok(created) => Ok((
                            process_id,
                            created.version,
                            created.definition_key,
                            created.instance_key,
                            created.sync_completed,
                            created.routable,
                            created.commit,
                        )),
                        Err(EngineError::ProcessNotFound { process_id }) => {
                            Err((400, format!("No deployed process with id '{process_id}'.")))
                        }
                        Err(e) => Err((500, e.to_string())),
                    }
                })
                .await
        };
        let (process_id, version, definition_key, instance_key, sync_completed, routable, commit) =
            outcome?;
        // Count the forwarded create exactly once, here at the committing owner,
        // under the ORIGINAL client transport (`origin_protocol`) rather than a
        // hardcoded "rest". The forwarding node deliberately does NOT record a
        // create it hands off (see `create_via_raft` / `create_for_stream`), so
        // `nanobpm_creates_total` reflects real instances 1:1 instead of
        // double-counting every forwarded create (once at ingress, once here).
        crate::metrics::record_create(origin_protocol);
        commit.wait().await;
        if !routable.is_empty() {
            self.drive_subscription_routing(routable).await;
        }
        self.signal_jobs_available();
        let (variables_out, process_completed) = if await_completion {
            self.await_process_completion(instance_key, fetch_variables.as_ref(), request_timeout)
                .await
        } else {
            (std::collections::HashMap::new(), sync_completed)
        };
        let result = models::CreateProcessInstanceResult::new(
            process_id,
            version,
            "<default>".to_string(),
            variables_out,
            models::ProcessDefinitionKey(definition_key),
            models::ProcessInstanceKey(instance_key.to_string()),
            tags_for_response.into_iter().map(models::Tag).collect(),
            business_id_for_response
                .map(nanobpm_gateway_rest::types::Nullable::Present)
                .unwrap_or(nanobpm_gateway_rest::types::Nullable::Null),
            process_completed,
        );
        serde_json::to_value(&result).map_err(|e| (500, e.to_string()))
    }

    /// Gateway side of cluster-wide create placement: forwards a
    /// `createProcessInstance` to peer `node` and maps its answer to the REST
    /// response. Used when this gateway's round-robin placement lands on a
    /// partition owned by another node.
    #[allow(clippy::too_many_arguments)]
    #[allow(clippy::too_many_arguments)]
    async fn forward_create(
        &self,
        node: u32,
        by_id: Option<String>,
        by_key: Option<String>,
        variables: Option<serde_json::Map<String, serde_json::Value>>,
        tags: Vec<String>,
        business_id: Option<String>,
        await_completion: bool,
        fetch_variables: Option<Vec<String>>,
        request_timeout: Option<i64>,
    ) -> apis::process_instance::CreateProcessInstanceResponse {
        use apis::process_instance::CreateProcessInstanceResponse as Resp;
        let outcome = self
            .forward_create_once(
                node,
                by_id,
                by_key,
                variables,
                tags,
                business_id,
                await_completion,
                fetch_variables,
                request_timeout,
            )
            .await;
        match outcome {
            ForwardCreateOutcome::Created(result) => {
                Resp::Status200_TheProcessInstanceWasCreated(result)
            }
            ForwardCreateOutcome::Reject400(detail) => {
                Resp::Status400_TheProvidedDataIsNotValid(problem("Invalid create", 400, detail))
            }
            // Without placement protection a peer never placement-sheds, so this
            // is only reached defensively; surface it as a retryable error.
            ForwardCreateOutcome::Shed(detail) => {
                Resp::Status500_AnInternalErrorOccurredWhileProcessingTheRequest(problem(
                    "Peer error",
                    503,
                    detail,
                ))
            }
            ForwardCreateOutcome::Unreachable(detail) => {
                Resp::Status500_AnInternalErrorOccurredWhileProcessingTheRequest(problem(
                    "Peer error",
                    502,
                    detail,
                ))
            }
            ForwardCreateOutcome::Error(status, detail) => {
                Resp::Status500_AnInternalErrorOccurredWhileProcessingTheRequest(problem(
                    "Peer error",
                    status,
                    detail,
                ))
            }
        }
    }

    /// Forwards a `createProcessInstance` to peer `node` and classifies the
    /// answer into a [`ForwardCreateOutcome`], distinguishing a rerouteable
    /// **placement shed** (the peer is saturated, ADR 0014 `protect`) and an
    /// unreachable peer from a terminal result. The ingress reroute loop uses the
    /// `Shed`/`Unreachable` outcomes to re-place onto another owner;
    /// [`forward_create`](Self::forward_create) maps the outcome straight to an
    /// HTTP response for the non-protected path.
    #[allow(clippy::too_many_arguments)]
    async fn forward_create_once(
        &self,
        node: u32,
        by_id: Option<String>,
        by_key: Option<String>,
        variables: Option<serde_json::Map<String, serde_json::Value>>,
        tags: Vec<String>,
        business_id: Option<String>,
        await_completion: bool,
        fetch_variables: Option<Vec<String>>,
        request_timeout: Option<i64>,
    ) -> ForwardCreateOutcome {
        let res = match self.peer_link(node).await {
            Ok(link) => {
                link.forward_create(
                    by_id,
                    by_key,
                    variables,
                    tags,
                    business_id,
                    await_completion,
                    fetch_variables,
                    request_timeout,
                    "rest",
                )
                .await
            }
            Err((_, m)) => return ForwardCreateOutcome::Unreachable(m),
        };
        match res {
            Ok(r) if is_ok_status(r.status) => {
                match r.body.and_then(|b| {
                    serde_json::from_value::<models::CreateProcessInstanceResult>(b).ok()
                }) {
                    Some(result) => ForwardCreateOutcome::Created(result),
                    None => ForwardCreateOutcome::Error(
                        500,
                        "peer returned an unparseable create result".into(),
                    ),
                }
            }
            Ok(r) if r.status == 400 => ForwardCreateOutcome::Reject400(peer_detail(&r)),
            // The peer self-protected and shed this create back for rerouting
            // (ADR 0014): a 503 tagged with the placement-shed marker.
            Ok(r) if r.status == 503 => {
                let detail = peer_detail(&r);
                if detail.starts_with(PLACEMENT_SHED_MARKER) {
                    ForwardCreateOutcome::Shed(detail)
                } else {
                    ForwardCreateOutcome::Error(503, detail)
                }
            }
            Ok(r) => ForwardCreateOutcome::Error(500, peer_detail(&r)),
            // A transport error AFTER the request was sent is ambiguous — the peer
            // may have applied the create — so it is NOT rerouted (that would risk
            // a duplicate instance); it surfaces as a retryable error instead.
            Err(e) => ForwardCreateOutcome::Error(502, e.to_string()),
        }
    }

    /// Load-aware weighted create placement (ADR 0014 `balanced`). Enumerates
    /// every partition's owner, weights each inversely to its gossiped composite
    /// load (a shedding, or already-`tried`, owner gets weight 0 and is never
    /// picked; an unprobed peer is treated as full headroom), and selects one via
    /// smooth weighted round-robin ([`crate::placement::swrr_pick`]) over the
    /// persistent per-partition smoothing state. Equal loads therefore yield an
    /// exact round-robin (creates spread evenly); skewed loads steer smoothly
    /// toward headroom. Returns `Some(node)` to forward to a peer, or `None` to
    /// create locally (a local slot won the weighting, or no eligible remote owner
    /// remained).
    fn next_create_placement_weighted(&self, tried: &[u32]) -> Option<u32> {
        let n = self.engine.partition_count();
        if n <= 1 {
            return None;
        }
        let owners: Vec<Option<u32>> = (0..n as u64).map(|p| self.engine.owner_of(p)).collect();
        let local_weight = crate::placement::placement_weight(self.create_load_index());
        let weights: Vec<u128> = owners
            .iter()
            .map(|owner| match owner {
                None => local_weight,
                Some(node) if tried.contains(node) => 0,
                Some(node) => {
                    // A peer that has not gossiped yet is treated as full
                    // headroom (load 0) so it still receives traffic; the
                    // reactive shed/reroute layer corrects an over-optimistic
                    // guess.
                    crate::placement::placement_weight(self.peer_load(*node).unwrap_or(0))
                }
            })
            .collect();
        let mut cur = self
            .placement_swrr
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        if cur.len() != n {
            cur.resize(n, 0);
        }
        crate::placement::swrr_pick(&weights, &mut cur).and_then(|i| owners[i])
    }

    /// Ingress reroute loop for create-placement protection (ADR 0014). Forwards
    /// the create to `first`, and if the owner placement-sheds (or is
    /// unreachable) re-places onto another owner — blind round-robin skipping
    /// tried owners in `protect`, load-weighted in `balanced` — until a peer
    /// accepts, a terminal result arrives, or every owner is exhausted. Returns
    /// `Some(resp)` when the create is resolved remotely (success / 400 / error /
    /// final shed), or `None` to fall through to a **local** create — either
    /// because placement chose this node, or as the last-resort backstop when the
    /// whole cluster shed (the ingress node already passed its own admission gate,
    /// so a local create is the honest floor rather than a spurious 503).
    #[allow(clippy::too_many_arguments)]
    async fn forward_create_rerouting(
        &self,
        first: Option<u32>,
        by_id: Option<String>,
        by_key: Option<String>,
        variables: Option<serde_json::Map<String, serde_json::Value>>,
        tags: Vec<String>,
        business_id: Option<String>,
        await_completion: bool,
        fetch_variables: Option<Vec<String>>,
        request_timeout: Option<i64>,
    ) -> Option<apis::process_instance::CreateProcessInstanceResponse> {
        use apis::process_instance::CreateProcessInstanceResponse as Resp;
        let mut tried: Vec<u32> = Vec::new();
        let bound = self.engine.partition_count().max(1) + 1;
        let mut target = first;
        for _ in 0..bound {
            let Some(node) = target else {
                // Local placement (or exhausted) -> caller does a local create.
                return None;
            };
            let outcome = self
                .forward_create_once(
                    node,
                    by_id.clone(),
                    by_key.clone(),
                    variables.clone(),
                    tags.clone(),
                    business_id.clone(),
                    await_completion,
                    fetch_variables.clone(),
                    request_timeout,
                )
                .await;
            match outcome {
                ForwardCreateOutcome::Created(result) => {
                    return Some(Resp::Status200_TheProcessInstanceWasCreated(result));
                }
                ForwardCreateOutcome::Reject400(detail) => {
                    return Some(Resp::Status400_TheProvidedDataIsNotValid(problem(
                        "Invalid create",
                        400,
                        detail,
                    )));
                }
                ForwardCreateOutcome::Error(status, detail) => {
                    return Some(
                        Resp::Status500_AnInternalErrorOccurredWhileProcessingTheRequest(problem(
                            "Peer error",
                            status,
                            detail,
                        )),
                    );
                }
                // Rerouteable: the owner shed (saturated) or was unreachable.
                ForwardCreateOutcome::Shed(_) | ForwardCreateOutcome::Unreachable(_) => {
                    tried.push(node);
                    target = if self.placement_mode.balances() {
                        self.next_create_placement_weighted(&tried)
                    } else {
                        self.engine.next_create_placement_avoiding(&tried)
                    };
                }
            }
        }
        // Every candidate shed: fall through to a local create (last resort).
        None
    }

    /// Forwards a non-`await_completion` create to the current create-leader with
    /// a short per-attempt deadline ([`write_forward_timeout`]) and leader
    /// re-resolution across a total budget ([`write_forward_retry_budget`]). When
    /// the targeted leader has just failed (e.g. a node left the network), the
    /// per-attempt forward times out fast instead of pinning the caller for the
    /// 30s general peer timeout; the loop then re-resolves the leader — which the
    /// surviving replicas elect within the election timeout — and retries against
    /// it. Converts a single-node loss from a closed-loop throughput collapse into
    /// a brief blip while leadership moves. Business/validation rejections (400/409)
    /// short-circuit; transient transport/leadership errors retry until the budget
    /// is spent, then surface a retryable 503.
    #[allow(clippy::too_many_arguments)]
    async fn forward_create_bounded(
        &self,
        by_id: Option<String>,
        by_key: Option<String>,
        wire_vars: Option<serde_json::Map<String, serde_json::Value>>,
        tags: Vec<String>,
        business_id: Option<String>,
        fetch_variables: Option<Vec<String>>,
        request_timeout: Option<i64>,
    ) -> apis::process_instance::CreateProcessInstanceResponse {
        use apis::process_instance::CreateProcessInstanceResponse as Resp;
        let started = std::time::Instant::now();
        let budget = write_forward_retry_budget();
        let per_try = write_forward_timeout();
        let mut last_detail = "no partition leader reachable; retry".to_string();

        loop {
            let Some(node) = self.leader_node_for_create() else {
                // No known leader yet (mid-election): wait briefly, then retry
                // until the budget is spent.
                if started.elapsed() >= budget {
                    break;
                }
                tokio::time::sleep(std::time::Duration::from_millis(50)).await;
                continue;
            };

            let link = match self.peer_link(node).await {
                Ok(link) => link,
                Err((_, m)) => {
                    last_detail = m;
                    if started.elapsed() >= budget {
                        break;
                    }
                    tokio::time::sleep(std::time::Duration::from_millis(50)).await;
                    continue;
                }
            };

            let res = link
                .forward_create_within(
                    per_try,
                    by_id.clone(),
                    by_key.clone(),
                    wire_vars.clone(),
                    tags.clone(),
                    business_id.clone(),
                    fetch_variables.clone(),
                    request_timeout,
                    "stream",
                )
                .await;

            match res {
                Ok(r) if is_ok_status(r.status) => {
                    return match r.body.and_then(|b| {
                        serde_json::from_value::<models::CreateProcessInstanceResult>(b).ok()
                    }) {
                        Some(result) => Resp::Status200_TheProcessInstanceWasCreated(result),
                        None => Resp::Status500_AnInternalErrorOccurredWhileProcessingTheRequest(
                            problem(
                                "Peer error",
                                500,
                                "peer returned an unparseable create result".into(),
                            ),
                        ),
                    };
                }
                // Deterministic client rejection: do not retry.
                Ok(r) if r.status == 400 => {
                    return Resp::Status400_TheProvidedDataIsNotValid(problem(
                        "Invalid create",
                        400,
                        peer_detail(&r),
                    ));
                }
                Ok(r) if r.status == 409 => {
                    return Resp::Status409_TheProcessInstanceCreationWasRejectedDueToABusinessIDUniquenessConflict(
                        problem("Conflict", 409, peer_detail(&r)),
                    );
                }
                // Transient (peer 5xx, timeout, closed): re-resolve leader & retry.
                Ok(r) => last_detail = peer_detail(&r),
                Err(e) => last_detail = e.to_string(),
            }

            if started.elapsed() >= budget {
                break;
            }
            tokio::time::sleep(std::time::Duration::from_millis(25)).await;
        }

        Resp::Status503_TheServiceIsCurrentlyUnavailable(problem(
            "RESOURCE_EXHAUSTED",
            503,
            format!("create could not reach a partition leader; retry ({last_detail})"),
        ))
    }

    /// Publishes a message and correlates it to any matching open subscriptions.
    /// nanobpmn does not buffer messages (no TTL/dedup): the message is minted,
    /// correlated to every matching open subscription, then dropped. Always
    /// returns 200 with the minted message key.
    async fn publish_message_impl(
        &self,
        body: &models::MessagePublicationRequest,
    ) -> Result<apis::message::PublishMessageResponse, ()> {
        use apis::message::PublishMessageResponse as Resp;

        let correlation_key = body.correlation_key.clone().unwrap_or_default();
        let variables = wire_variables(body.variables.as_ref());

        let body_name = body.name.clone();
        let (message_key, _instance) = match self
            .correlate_message_cluster(
                body_name,
                correlation_key,
                variables,
                body.business_id.clone(),
            )
            .await
        {
            Ok(correlated) => correlated,
            // An out-of-range businessId (the only correlation failure).
            Err(e) => {
                return Ok(Resp::Status400_TheProvidedDataIsNotValid(problem(
                    "INVALID_ARGUMENT",
                    400,
                    e.to_string(),
                )));
            }
        };

        // Correlation may have advanced a token onto a service task, creating a
        // new activatable job: wake any long-pollers.
        self.signal_jobs_available();

        let result = models::MessagePublicationResult::new(
            "<default>".to_string(),
            models::MessageKey(message_key.to_string()),
        );
        Ok(Resp::Status200_TheMessageWasPublished(result))
    }

    /// Correlates a message to a matching open subscription. Unlike
    /// [`Self::publish_message_impl`], returns 404 when nothing correlates, and
    /// reports the first correlated process instance.
    async fn correlate_message_impl(
        &self,
        body: &models::MessageCorrelationRequest,
    ) -> Result<apis::message::CorrelateMessageResponse, ()> {
        use apis::message::CorrelateMessageResponse as Resp;

        let correlation_key = body.correlation_key.clone().unwrap_or_default();
        let variables = wire_variables(body.variables.as_ref());

        let body_name = body.name.clone();
        let (message_key, correlated_instance) = match self
            .correlate_message_cluster(
                body_name,
                correlation_key,
                variables,
                body.business_id.clone(),
            )
            .await
        {
            Ok(correlated) => correlated,
            // An out-of-range businessId (the only correlation failure).
            Err(e) => {
                return Ok(Resp::Status400_TheProvidedDataIsNotValid(problem(
                    "INVALID_ARGUMENT",
                    400,
                    e.to_string(),
                )));
            }
        };
        // A message correlates either to an existing instance's open subscription
        // (MessageCorrelated) or, via a message start event, by creating a new
        // instance (ProcessInstanceCreated). Either way it correlated to an
        // instance; report the first matched instance key.

        match correlated_instance {
            Some(instance_key) => {
                // Correlation may have advanced a token onto a service task,
                // creating a new activatable job: wake any long-pollers.
                self.signal_jobs_available();
                let result = models::MessageCorrelationResult::new(
                    "<default>".to_string(),
                    models::MessageKey(message_key.to_string()),
                    models::ProcessInstanceKey(instance_key.to_string()),
                );
                Ok(Resp::Status200_TheMessageIsCorrelatedToOneOrMoreProcessInstances(result))
            }
            None => Ok(Resp::Status404_NotFound(problem(
                "Message not correlated",
                404,
                format!(
                    "No open subscription matched message '{}' with the given correlation key.",
                    body.name
                ),
            ))),
        }
    }

    async fn get_incident_impl(
        &self,
        path_params: &models::GetIncidentPathParams,
    ) -> Result<apis::incident::GetIncidentResponse, ()> {
        use apis::incident::GetIncidentResponse as Resp;

        let key: u64 = match path_params.incident_key.parse() {
            Ok(k) => k,
            Err(_) => {
                return Ok(Resp::Status404_TheIncidentWithTheGivenKeyWasNotFound(
                    problem(
                        "Incident not found",
                        404,
                        format!(
                            "Incident key '{}' is not a valid key.",
                            path_params.incident_key
                        ),
                    ),
                ));
            }
        };

        let result = self.store.incident(key);
        if result.is_none()
            && let Some(node) = self.read_route(key)
        {
            let (status, body) = self
                .forward_get(node, crate::falcon::ReadKind::Incident, key)
                .await;
            return Ok(match (status, body) {
                (200, Some(b)) => match serde_json::from_value(b) {
                    Ok(r) => Resp::Status200_TheIncidentIsSuccessfullyReturned(r),
                    Err(e) => Resp::Status500_AnInternalErrorOccurredWhileProcessingTheRequest(
                        problem("Peer error", 500, e.to_string()),
                    ),
                },
                (404, _) => Resp::Status404_TheIncidentWithTheGivenKeyWasNotFound(problem(
                    "Incident not found",
                    404,
                    format!("No incident with key {key}."),
                )),
                (s, _) => {
                    Resp::Status500_AnInternalErrorOccurredWhileProcessingTheRequest(problem(
                        "Peer error",
                        500,
                        format!("peer node {node} returned status {s}"),
                    ))
                }
            });
        }
        match result {
            Some(incident) => Ok(Resp::Status200_TheIncidentIsSuccessfullyReturned(
                incident_result(&incident),
            )),
            None => Ok(Resp::Status404_TheIncidentWithTheGivenKeyWasNotFound(
                problem(
                    "Incident not found",
                    404,
                    format!("No incident with key {key}."),
                ),
            )),
        }
    }

    async fn search_incidents_impl(
        &self,
        body: &Option<models::IncidentSearchQuery>,
    ) -> Result<apis::incident::SearchIncidentsResponse, ()> {
        use apis::incident::SearchIncidentsResponse as Resp;

        let filter = body.as_ref().and_then(|q| q.filter.as_ref());
        let incidents = self.store.incidents();

        // Apply the filter algebra over each incident's string projections. The
        // process-definition identity is denormalized onto the row at projection
        // time, so no cross-entity lookup is needed here.
        let mut matched: Vec<&readstore::IncidentRow> = incidents
            .iter()
            .filter(|inc| match filter {
                None => true,
                Some(f) => {
                    query::match_basic_string(&f.incident_key, &inc.key.to_string())
                        && query::match_process_instance_key(
                            &f.process_instance_key,
                            &inc.instance_key.to_string(),
                        )
                        && query::match_element_instance_key(
                            &f.element_instance_key,
                            &inc.element_instance_key.to_string(),
                        )
                        && query::match_process_definition_key(
                            &f.process_definition_key,
                            &inc.process_definition_key,
                        )
                        && query::match_job_key_opt(
                            &f.job_key,
                            inc.job_key.map(|k| k.to_string()).as_deref(),
                        )
                        && query::match_incident_state(
                            &f.state,
                            &incident_state_enum(inc.state).to_string(),
                        )
                        && query::match_incident_error_type(
                            &f.error_type,
                            &incident_error_type_enum(inc.kind).to_string(),
                        )
                        && query::match_string(&f.element_id, &inc.element_id)
                        && query::match_string(&f.error_message, &inc.reason)
                }
            })
            .collect();

        // Sort: known fields, defaulting to incidentKey; entity key tiebreaks.
        let sort = query::sort_keys(
            body.as_ref().and_then(|q| q.sort.as_ref()),
            |r: &models::IncidentSearchQuerySortRequest| (r.field.clone(), r.order),
        );
        query::sort_items(
            &mut matched,
            &sort,
            |inc, field| match field {
                "creationTime" => query::SortVal::Num(inc.created_at_ms as i64),
                "state" => query::SortVal::Str(incident_state_enum(inc.state).to_string()),
                "errorType" => query::SortVal::Str(incident_error_type_enum(inc.kind).to_string()),
                "processInstanceKey" => query::SortVal::Num(inc.instance_key as i64),
                "elementId" => query::SortVal::Str(inc.element_id.clone()),
                _ => query::SortVal::Num(inc.key as i64),
            },
            |inc| inc.key,
        );

        let sorted: Vec<(u64, &readstore::IncidentRow)> =
            matched.into_iter().map(|inc| (inc.key, inc)).collect();
        let page = query::paginate(sorted, body.as_ref().and_then(|q| q.page.as_ref()));
        let items: Vec<models::IncidentResult> =
            page.items.into_iter().map(incident_result).collect();

        Ok(Resp::Status200_TheIncidentSearchResult(
            models::IncidentSearchQueryResult::new(page.response, items),
        ))
    }

    /// Searches incidents scoped to a single "root" element instance (path
    /// parameter): the element instance itself plus every element instance
    /// contained transitively within its variable/token scope subtree (embedded
    /// sub-processes, multi-instance bodies). Nano expands call activities inline
    /// at deploy time, so this subtree — not a separate child process instance —
    /// is where a call activity's incidents live. Reuses the incident read model
    /// and the same `IncidentSearchQuery` filter algebra as `searchIncidents`,
    /// intersecting matches with the scope subtree. Returns 404 when the path
    /// element instance is unknown to this node's read model.
    async fn search_element_instance_incidents_impl(
        &self,
        path_params: &models::SearchElementInstanceIncidentsPathParams,
        body: &models::IncidentSearchQuery,
    ) -> Result<apis::element_instance::SearchElementInstanceIncidentsResponse, ()> {
        use apis::element_instance::SearchElementInstanceIncidentsResponse as Resp;

        let root_key: u64 = match path_params.element_instance_key.parse() {
            Ok(k) => k,
            Err(_) => {
                return Ok(
                    Resp::Status404_TheElementInstanceWithTheGivenKeyWasNotFound(problem(
                        "Element instance not found",
                        404,
                        format!(
                            "Element instance key '{}' is not a valid key.",
                            path_params.element_instance_key
                        ),
                    )),
                );
            }
        };

        let element_instances = self.store.element_instances();
        let Some(root) = element_instances
            .iter()
            .find(|ei| ei.element_instance_key == root_key)
        else {
            return Ok(
                Resp::Status404_TheElementInstanceWithTheGivenKeyWasNotFound(problem(
                    "Element instance not found",
                    404,
                    format!("No element instance with key {root_key}."),
                )),
            );
        };

        // Transitive scope-subtree closure rooted at `root_key`: an element
        // instance is contained if it *is* the root or its enclosing scope is
        // already contained. All descendants share the root's process instance,
        // so only that instance's rows are considered. Build a scope→children
        // adjacency once (restricted to the root's process instance) and walk it
        // with a single BFS (O(n)), rather than rescanning to a fixpoint.
        let mut children: std::collections::HashMap<u64, Vec<u64>> =
            std::collections::HashMap::new();
        for ei in &element_instances {
            if ei.instance_key == root.instance_key {
                children
                    .entry(ei.scope_key)
                    .or_default()
                    .push(ei.element_instance_key);
            }
        }
        let mut contained: std::collections::HashSet<u64> = std::collections::HashSet::new();
        let mut frontier = vec![root_key];
        contained.insert(root_key);
        while let Some(scope) = frontier.pop() {
            if let Some(kids) = children.get(&scope) {
                for &child in kids {
                    if contained.insert(child) {
                        frontier.push(child);
                    }
                }
            }
        }

        let filter = body.filter.as_ref();
        let incidents = self.store.incidents();
        let mut matched: Vec<&readstore::IncidentRow> = incidents
            .iter()
            .filter(|inc| contained.contains(&inc.element_instance_key))
            .filter(|inc| match filter {
                None => true,
                Some(f) => {
                    query::match_basic_string(&f.incident_key, &inc.key.to_string())
                        && query::match_process_instance_key(
                            &f.process_instance_key,
                            &inc.instance_key.to_string(),
                        )
                        && query::match_element_instance_key(
                            &f.element_instance_key,
                            &inc.element_instance_key.to_string(),
                        )
                        && query::match_process_definition_key(
                            &f.process_definition_key,
                            &inc.process_definition_key,
                        )
                        && query::match_job_key_opt(
                            &f.job_key,
                            inc.job_key.map(|k| k.to_string()).as_deref(),
                        )
                        && query::match_incident_state(
                            &f.state,
                            &incident_state_enum(inc.state).to_string(),
                        )
                        && query::match_incident_error_type(
                            &f.error_type,
                            &incident_error_type_enum(inc.kind).to_string(),
                        )
                        && query::match_string(&f.element_id, &inc.element_id)
                        && query::match_string(&f.error_message, &inc.reason)
                }
            })
            .collect();

        let sort = query::sort_keys(
            body.sort.as_ref(),
            |r: &models::IncidentSearchQuerySortRequest| (r.field.clone(), r.order),
        );
        query::sort_items(
            &mut matched,
            &sort,
            |inc, field| match field {
                "creationTime" => query::SortVal::Num(inc.created_at_ms as i64),
                "state" => query::SortVal::Str(incident_state_enum(inc.state).to_string()),
                "errorType" => query::SortVal::Str(incident_error_type_enum(inc.kind).to_string()),
                "processInstanceKey" => query::SortVal::Num(inc.instance_key as i64),
                "elementId" => query::SortVal::Str(inc.element_id.clone()),
                _ => query::SortVal::Num(inc.key as i64),
            },
            |inc| inc.key,
        );

        let sorted: Vec<(u64, &readstore::IncidentRow)> =
            matched.into_iter().map(|inc| (inc.key, inc)).collect();
        let page = query::paginate(sorted, body.page.as_ref());
        let items: Vec<models::IncidentResult> =
            page.items.into_iter().map(incident_result).collect();

        Ok(Resp::Status200_TheElementInstanceIncidentSearchResult(
            models::IncidentSearchQueryResult::new(page.response, items),
        ))
    }

    /// Searches element-instance wait states: element instances currently parked
    /// waiting on an external interaction. Three sources feed it — active jobs
    /// (`JOB`, waiting for a worker) from the jobs read model, open message
    /// subscriptions (`MESSAGE`, waiting for a correlated message) from the
    /// message-subscription read model, and open native user tasks (`USER_TASK`,
    /// waiting for a human) from the user-task read model. A concrete
    /// `waitStateType` filter skips the sources it excludes (see `wants` below).
    /// `rootProcessInstanceKey` resolves to the
    /// top-level ancestor by walking the `parentProcessInstanceKey` chain (issue
    /// #977) — a top-level instance roots to its own key, a call-activity child
    /// (issue #808) to the true top-level instance; see `element_instance_result`.
    /// Local read-model scan, matching the other
    /// `search*` endpoints.
    async fn search_element_instance_wait_states_impl(
        &self,
        body: &Option<models::ElementInstanceWaitStateQuery>,
    ) -> Result<apis::element_instance::SearchElementInstanceWaitStatesResponse, ()> {
        use apis::element_instance::SearchElementInstanceWaitStatesResponse as Resp;

        let filter = body.as_ref().and_then(|q| q.filter.as_ref());

        // `elementType` and `tenantId` are resolved from the element-instance
        // read model (the jobs/subscriptions rows do not carry them).
        let element_instances = self.store.element_instances();
        let ei_by_key: std::collections::HashMap<u64, &readstore::ElementInstanceRow> =
            element_instances
                .iter()
                .map(|e| (e.element_instance_key, e))
                .collect();
        let resolve = |eik: u64, fallback_element_id: &str| -> (String, String, String) {
            match ei_by_key.get(&eik) {
                Some(ei) => (
                    ei.element_type.clone(),
                    if ei.tenant_id.is_empty() {
                        "<default>".to_string()
                    } else {
                        ei.tenant_id.clone()
                    },
                    ei.element_id.clone(),
                ),
                None => (
                    "UNKNOWN".to_string(),
                    "<default>".to_string(),
                    fallback_element_id.to_string(),
                ),
            }
        };

        struct WaitState {
            element_instance_key: u64,
            /// The key of the wait's own source (job / subscription / user task /
            /// timer), all from one engine key space. An element instance can
            /// hold several waits (a job plus its boundary timer), so the
            /// tiebreak and the pagination cursor are `(element_instance_key,
            /// source_key)` — unique per row, as `query::paginate` requires.
            source_key: u64,
            process_instance_key: u64,
            element_id: String,
            element_type: String,
            tenant_id: String,
            /// The discriminated wait-state details; the wait-state type is
            /// derived from it (`wait_state_type_of`), never stored alongside.
            details: models::WaitStateDetails,
        }

        let mut states: Vec<WaitState> = Vec::new();

        // Whether a wait-state source can contribute any row under the current
        // `waitStateType` filter. This endpoint is polled, and each source below
        // performs a full cross-shard read-model scan, so a concrete
        // `waitStateType` (e.g. `MESSAGE`) would otherwise still scan the jobs and
        // user-task stores only to discard every row post-collection. The guard
        // reuses `match_wait_state_type` — the same predicate the post-collection
        // filter applies — so type matching stays a single source of truth (no
        // duplicated enum logic to drift), and it short-circuits every source
        // uniformly rather than special-casing one.
        let wants = |t: models::WaitStateTypeEnum| {
            filter.is_none_or(|f| query::match_wait_state_type(&f.wait_state_type, &t.to_string()))
        };

        // JOB wait states: an element instance parked on an activatable/locked
        // job (`Created`/`Activated`). Failed/terminal jobs are not wait states.
        let jobs = if wants(models::WaitStateTypeEnum::Job) {
            self.store.jobs()
        } else {
            Vec::new()
        };
        for job in jobs {
            use nanobpmn_engine_core::JobState;
            if !matches!(job.state, JobState::Created | JobState::Activated) {
                continue;
            }
            let (element_type, tenant_id, element_id) =
                resolve(job.element_instance_key, &job.element_id);
            let (job_kind, listener_event_type_enum) = job_kind_enums(&job.kind);
            // `listenerEventType` is only meaningful for listener jobs.
            let listener_event_type = if matches!(job_kind, models::JobKindEnum::BpmnElement) {
                types::Nullable::Null
            } else {
                types::Nullable::Present(listener_event_type_enum)
            };
            states.push(WaitState {
                element_instance_key: job.element_instance_key,
                source_key: job.key,
                process_instance_key: job.instance_key,
                element_id,
                element_type,
                tenant_id,
                details: models::JobWaitStateDetails::new(
                    models::JobKey(job.key.to_string()),
                    job.job_type.clone(),
                    job_kind,
                    listener_event_type,
                    types::Nullable::Present(job.retries),
                )
                .into(),
            });
        }

        // MESSAGE wait states: an element instance parked on an open message
        // subscription. Correlation key is null for start events (never tracked
        // here) so an empty stored key projects as null.
        let message_subscriptions = if wants(models::WaitStateTypeEnum::Message) {
            self.store.message_subscriptions()
        } else {
            Vec::new()
        };
        for sub in message_subscriptions {
            let (element_type, tenant_id, element_id) =
                resolve(sub.element_instance_key, &sub.element_id);
            let correlation_key = if sub.correlation_key.is_empty() {
                types::Nullable::Null
            } else {
                types::Nullable::Present(sub.correlation_key.clone())
            };
            states.push(WaitState {
                element_instance_key: sub.element_instance_key,
                source_key: sub.subscription_key,
                process_instance_key: sub.instance_key,
                element_id,
                element_type,
                tenant_id,
                details: models::MessageWaitStateDetails::new(
                    sub.message_name.clone(),
                    correlation_key,
                )
                .into(),
            });
        }

        // USER_TASK wait states: an element instance parked on an open (native)
        // user task. Two distinct things share the word "task" here, so keep them
        // separate: the underlying `user_tasks` read-model *row* and the derived
        // wait-state *view* projected from it. Canonical Camunda lifecycle — the
        // row is inserted on `UserTaskCreated` and transitions to a terminal state
        // (`COMPLETED`/`CANCELED`) on completion/cancellation; the row is retained
        // with that terminal state, it is not deleted. The derived wait-state view
        // exists only while the row is still `Created`, so an *open* park is
        // exactly a row in `Created` and terminal rows contribute nothing. The
        // park carries the user-task element instance's own
        // `elementId`/`elementType: USER_TASK`, plus `taskKey` (and `dueDate` when
        // the task declared one).
        let user_tasks = if wants(models::WaitStateTypeEnum::UserTask) {
            self.store.user_tasks()
        } else {
            Vec::new()
        };
        for task in user_tasks {
            use nanobpmn_engine_core::UserTaskState;
            if task.state != UserTaskState::Created {
                continue;
            }
            let (element_type, tenant_id, element_id) =
                resolve(task.element_instance_key, &task.element_id);
            let due_date = task
                .due_date
                .as_deref()
                .and_then(|s| s.parse::<chrono::DateTime<chrono::Utc>>().ok())
                .map(types::Nullable::Present)
                .unwrap_or(types::Nullable::Null);
            let details = models::UserTaskWaitStateDetails::new(
                models::UserTaskKey(task.key.to_string()),
                due_date,
            );
            states.push(WaitState {
                element_instance_key: task.element_instance_key,
                source_key: task.key,
                process_instance_key: task.instance_key,
                element_id,
                element_type,
                tenant_id,
                details: details.into(),
            });
        }

        // TIMER / SIGNAL / CONDITION wait states: an element instance parked on
        // (or guarded by a boundary for) an armed timer or an open signal /
        // conditional subscription. Engine timers are one-shot (no cycles), so
        // `repetitions` is always null; a conditional fires on any change to a
        // variable it references, so `events` is empty (= all events).
        let event_waits = if wants(models::WaitStateTypeEnum::Timer)
            || wants(models::WaitStateTypeEnum::Signal)
            || wants(models::WaitStateTypeEnum::Condition)
        {
            self.store.event_waits()
        } else {
            Vec::new()
        };
        for wait in event_waits {
            let details: models::WaitStateDetails = match wait.wait_type {
                readstore::EventWaitType::Timer => models::TimerWaitStateDetails::new(
                    wait.due_at_ms
                        .map(|d| types::Nullable::Present(d as i64))
                        .unwrap_or(types::Nullable::Null),
                    types::Nullable::Null,
                )
                .into(),
                readstore::EventWaitType::Signal => {
                    models::SignalWaitStateDetails::new(wait.detail.clone()).into()
                }
                readstore::EventWaitType::Condition => {
                    models::ConditionWaitStateDetails::new(wait.detail.clone(), Vec::new()).into()
                }
            };
            let (element_type, tenant_id, element_id) =
                resolve(wait.element_instance_key, &wait.element_id);
            states.push(WaitState {
                element_instance_key: wait.element_instance_key,
                source_key: wait.wait_key,
                process_instance_key: wait.instance_key,
                element_id,
                element_type,
                tenant_id,
                details,
            });
        }

        // One memoised root resolver for both the filter and projection passes,
        // so a wait state's root chain is walked once even though the two passes
        // each ask for it.
        let roots = readstore::RootResolver::new(|k| self.store.process_instance(k));
        let mut matched: Vec<WaitState> = states
            .into_iter()
            .filter(|ws| match filter {
                None => true,
                Some(f) => {
                    query::match_element_instance_key(
                        &f.element_instance_key,
                        &ws.element_instance_key.to_string(),
                    ) && query::match_process_instance_key(
                        &f.process_instance_key,
                        &ws.process_instance_key.to_string(),
                    ) && (
                        // Only resolve the (potentially multi-hop, per-row) root
                        // chain when a `rootProcessInstanceKey` filter is actually
                        // present — a `None` filter matches every row regardless,
                        // so resolving here would force a parent-chain lookup for
                        // every wait state before pagination for nothing (#977
                        // review). The paged projection below still resolves roots
                        // for the rows it returns.
                        f.root_process_instance_key.is_none()
                            || query::match_process_instance_key(
                                &f.root_process_instance_key,
                                &roots
                                    .root_process_instance_key(ws.process_instance_key)
                                    .to_string(),
                            )
                    ) && query::match_element_id(&f.element_id, &ws.element_id)
                        && query::match_wait_state_element_type(&f.element_type, &ws.element_type)
                        && query::match_wait_state_type(
                            &f.wait_state_type,
                            wait_state_type_of(&ws.details),
                        )
                }
            })
            .collect();

        // Sort by the requested fields (the shared search sort); the element
        // instance key tiebreaks, so the default (no sort) order is unchanged
        // and cursor pagination stays stable.
        let sort = query::sort_keys(
            body.as_ref().and_then(|q| q.sort.as_ref()),
            |r: &models::ElementInstanceWaitStateQuerySortRequest| (r.field.clone(), r.order),
        );
        query::sort_items(
            &mut matched,
            &sort,
            |ws, field| match field {
                "processInstanceKey" => query::SortVal::Num(ws.process_instance_key as i64),
                "rootProcessInstanceKey" => query::SortVal::Num(
                    roots.root_process_instance_key(ws.process_instance_key) as i64,
                ),
                "elementId" => query::SortVal::Str(ws.element_id.clone()),
                _ => query::SortVal::Num(ws.element_instance_key as i64),
            },
            |ws| (ws.element_instance_key, ws.source_key),
        );
        let sorted: Vec<((u64, u64), WaitState)> = matched
            .into_iter()
            .map(|ws| ((ws.element_instance_key, ws.source_key), ws))
            .collect();
        let page = query::paginate(sorted, body.as_ref().and_then(|q| q.page.as_ref()));
        let items: Vec<models::ElementInstanceWaitStateResult> = page
            .items
            .into_iter()
            .map(|ws| {
                // `bpmnProcessId` is the owning instance's process id; resolved
                // only for the returned page, like the root key above.
                let bpmn_process_id = self
                    .store
                    .process_instance(ws.process_instance_key)
                    .map(|pi| pi.process_id)
                    .unwrap_or_default();
                models::ElementInstanceWaitStateResult::new(
                    types::Nullable::Present(models::ProcessInstanceKey(
                        roots
                            .root_process_instance_key(ws.process_instance_key)
                            .to_string(),
                    )),
                    models::ProcessInstanceKey(ws.process_instance_key.to_string()),
                    models::ElementInstanceKey(ws.element_instance_key.to_string()),
                    ws.element_id,
                    wait_state_element_type(&ws.element_type),
                    ws.tenant_id,
                    bpmn_process_id,
                    ws.details,
                )
            })
            .collect();

        Ok(Resp::Status200_TheElementInstanceWaitStateSearchResult(
            models::ElementInstanceWaitStateQueryResult::new(page.response, items),
        ))
    }

    /// Returns a single decision instance by its `<decisionEvaluationKey>-<index>`
    /// id from the read model. A pure read; scans every owned shard because the
    /// composite id does not encode a partition.
    async fn get_decision_instance_impl(
        &self,
        path_params: &models::GetDecisionInstancePathParams,
    ) -> Result<apis::decision_instance::GetDecisionInstanceResponse, ()> {
        use apis::decision_instance::GetDecisionInstanceResponse as Resp;

        let key = &path_params.decision_evaluation_instance_key;
        match self.store.decision_instance(key) {
            Some(row) => Ok(Resp::Status200_TheDecisionInstanceIsSuccessfullyReturned(
                decision_instance_get_result(&row),
            )),
            None => Ok(
                Resp::Status404_TheDecisionInstanceWithTheGivenKeyWasNotFound(problem(
                    "Decision instance not found",
                    404,
                    format!("No decision instance with key '{key}'."),
                )),
            ),
        }
    }

    /// Marks a decision instance for deletion: retracts every read-model row that
    /// shares the given `decisionEvaluationKey` (one per evaluated decision in that
    /// evaluation). Durable and replay-safe — it journals an
    /// [`Event::DecisionInstanceDeleted`] on the owning process instance's
    /// partition (resolved from the local read-model row), so the row is deleted in
    /// the same shard that projected it and the deletion survives replay/rebuild.
    ///
    /// Scoped to this node's read model (like the decision-instance query
    /// endpoints, which do not scatter-gather across peers): a `decisionEvaluationKey`
    /// whose rows live only on a peer node returns 404 here.
    async fn delete_decision_instance_impl(
        &self,
        path_params: &models::DeleteDecisionInstancePathParams,
    ) -> Result<apis::decision_instance::DeleteDecisionInstanceResponse, ()> {
        use apis::decision_instance::DeleteDecisionInstanceResponse as Resp;

        let raw = &path_params.decision_evaluation_key;
        let decision_evaluation_key: u64 = match raw.parse() {
            Ok(k) => k,
            Err(_) => {
                return Ok(Resp::Status404_TheDecisionInstanceIsNotFound(problem(
                    "Decision instance not found",
                    404,
                    format!("Decision evaluation key '{raw}' is not a valid key."),
                )));
            }
        };

        // Resolve the owning process instance from the read model so the deletion
        // event is journaled on the shard that holds the rows. No rows => 404.
        let rows = self
            .store
            .decision_instances_by_evaluation_key(decision_evaluation_key);
        let Some(instance_key) = rows.first().map(|r| r.instance_key) else {
            return Ok(Resp::Status404_TheDecisionInstanceIsNotFound(problem(
                "Decision instance not found",
                404,
                format!("No decision instance for evaluation key '{raw}'."),
            )));
        };

        // A standalone evaluation (no process instance) was journaled on the
        // partition its minted evaluation key encodes; an instance's evaluation
        // on the instance's partition.
        let owner = nanobpmn_engine_core::dmn::decision_instance_owner_key(
            instance_key,
            decision_evaluation_key,
        );
        // Raft-aware: replicated through the owning partition's leader before
        // the 204 is acknowledged, so a failover cannot resurrect the rows.
        let result = self
            .apply_partition_command(
                owner,
                Command::DeleteDecisionInstance {
                    instance_key,
                    decision_evaluation_key,
                },
            )
            .await;
        match result {
            Ok((_events, commit)) => {
                commit.wait().await;
                Ok(Resp::Status204_TheDecisionInstanceIsMarkedForDeletion)
            }
            Err((503, detail)) => Ok(Resp::Status503_TheServiceIsCurrentlyUnavailable(problem(
                "Service unavailable",
                503,
                detail,
            ))),
            Err((_, detail)) => Ok(
                Resp::Status500_AnInternalErrorOccurredWhileProcessingTheRequest(problem(
                    "Internal error",
                    500,
                    detail,
                )),
            ),
        }
    }

    /// Searches decision instances in the read model, applying the filter algebra,
    /// multi-field sort, and pagination shared by the other `search*` endpoints.
    async fn search_decision_instances_impl(
        &self,
        body: &Option<models::DecisionInstanceSearchQuery>,
    ) -> Result<apis::decision_instance::SearchDecisionInstancesResponse, ()> {
        use apis::decision_instance::SearchDecisionInstancesResponse as Resp;

        let filter = body.as_ref().and_then(|q| q.filter.as_ref());
        let rows = self.store.decision_instances();

        let mut matched: Vec<&readstore::DecisionInstanceRow> = rows
            .iter()
            .filter(|row| match filter {
                None => true,
                Some(f) => {
                    query::match_decision_evaluation_instance_key(
                        &f.decision_evaluation_instance_key,
                        &row.eval_instance_key,
                    ) && query::match_decision_instance_state(&f.state, &row.state)
                        && f.evaluation_failure.as_ref().is_none_or(|want| {
                            row.evaluation_failure.as_deref() == Some(want.as_str())
                        })
                        && f.decision_definition_id
                            .as_ref()
                            .is_none_or(|want| want == &row.decision_id)
                        && f.decision_definition_name
                            .as_ref()
                            .is_none_or(|want| want == &row.decision_name)
                        && f.decision_definition_version
                            .is_none_or(|want| want == row.version)
                        && f.decision_definition_type
                            .as_ref()
                            .is_none_or(|want| want.to_string() == row.decision_type)
                        && f.tenant_id
                            .as_ref()
                            .is_none_or(|want| want == &row.tenant_id)
                        && f.decision_evaluation_key
                            .as_ref()
                            .is_none_or(|want| want.0 == row.decision_evaluation_key.to_string())
                        && f.process_definition_key
                            .as_ref()
                            .is_none_or(|want| want.0 == row.process_definition_key)
                        && f.process_instance_key
                            .as_ref()
                            .is_none_or(|want| want.0 == row.instance_key.to_string())
                        && query::match_decision_definition_key(
                            &f.decision_definition_key,
                            &row.decision_key.to_string(),
                        )
                        && query::match_element_instance_key(
                            &f.element_instance_key,
                            &row.element_instance_key.to_string(),
                        )
                        && query::match_decision_definition_key(
                            &f.root_decision_definition_key,
                            &row.root_decision_key.to_string(),
                        )
                        && query::match_decision_requirements_key(
                            &f.decision_requirements_key,
                            &row.decision_requirements_key.to_string(),
                        )
                        // The business id snapshotted at evaluation (a standalone
                        // evaluation has none, so it matches as an absent value).
                        && query::match_string_opt(&f.business_id, row.business_id.as_deref())
                }
            })
            .collect();

        // A unique cursor key for stable sort tiebreak + cursors. The decision
        // count within one evaluation is unbounded, so a synthetic
        // `decision_evaluation_key * 1000 + idx` collided (the 1,001st row of
        // evaluation `k` shared a key with the first row of evaluation `k + 1`),
        // breaking `paginate`'s unique-key requirement. The composite
        // `(decision_evaluation_key, idx)` is unique per row however large an
        // evaluation grows (#1305 review).
        let entity_key = |row: &readstore::DecisionInstanceRow| -> (u64, u64) {
            (row.decision_evaluation_key, row.idx as u64)
        };

        let sort = query::sort_keys(
            body.as_ref().and_then(|q| q.sort.as_ref()),
            |r: &models::DecisionInstanceSearchQuerySortRequest| (r.field.clone(), r.order),
        );
        query::sort_items(
            &mut matched,
            &sort,
            |row, field| match field {
                "evaluationDate" => query::SortVal::Num(row.evaluation_date_ms as i64),
                "decisionDefinitionId" => query::SortVal::Str(row.decision_id.clone()),
                "decisionDefinitionName" => query::SortVal::Str(row.decision_name.clone()),
                "decisionDefinitionKey" => query::SortVal::Num(row.decision_key as i64),
                "decisionDefinitionVersion" => query::SortVal::Num(row.version as i64),
                "decisionDefinitionType" => query::SortVal::Str(row.decision_type.clone()),
                "processInstanceKey" => query::SortVal::Num(row.instance_key as i64),
                "state" => query::SortVal::Str(row.state.clone()),
                "tenantId" => query::SortVal::Str(row.tenant_id.clone()),
                "decisionEvaluationInstanceKey" => {
                    query::SortVal::Str(row.eval_instance_key.clone())
                }
                "businessId" => query::SortVal::Str(row.business_id.clone().unwrap_or_default()),
                // Default (key) sort: by evaluation key, then the within-
                // evaluation index via the composite tiebreak below.
                _ => query::SortVal::Num(row.decision_evaluation_key as i64),
            },
            |row| entity_key(row),
        );

        let sorted: Vec<((u64, u64), &readstore::DecisionInstanceRow)> = matched
            .into_iter()
            .map(|row| (entity_key(row), row))
            .collect();
        let page = query::paginate(sorted, body.as_ref().and_then(|q| q.page.as_ref()));
        let items: Vec<models::DecisionInstanceResult> = page
            .items
            .into_iter()
            .map(decision_instance_result)
            .collect();

        Ok(Resp::Status200_TheDecisionInstanceSearchResult(
            models::DecisionInstanceSearchQueryResult::new(page.response, items),
        ))
    }

    async fn get_decision_definition_impl(
        &self,
        path_params: &models::GetDecisionDefinitionPathParams,
    ) -> Result<apis::decision_definition::GetDecisionDefinitionResponse, ()> {
        use apis::decision_definition::GetDecisionDefinitionResponse as Resp;

        let raw = &path_params.decision_definition_key;
        let key: u64 = match raw.parse() {
            Ok(k) => k,
            Err(_) => {
                return Ok(
                    Resp::Status404_TheDecisionDefinitionWithTheGivenKeyWasNotFound(problem(
                        "Decision definition not found",
                        404,
                        format!("Decision definition key '{raw}' is not a valid key."),
                    )),
                );
            }
        };

        match self.store.decision_definition_by_key(key) {
            Some(row) => Ok(Resp::Status200_TheDecisionDefinitionIsSuccessfullyReturned(
                decision_definition_result(&row),
            )),
            None => Ok(
                Resp::Status404_TheDecisionDefinitionWithTheGivenKeyWasNotFound(problem(
                    "Decision definition not found",
                    404,
                    format!("No decision definition with key {key}."),
                )),
            ),
        }
    }

