    async fn get_resource_content_impl(
        &self,
        path_params: &models::GetResourceContentPathParams,
    ) -> Result<apis::resource::GetResourceContentResponse, ()> {
        use apis::resource::GetResourceContentResponse as Resp;

        let raw = &path_params.resource_key;
        let key: u64 = match raw.parse() {
            Ok(k) => k,
            Err(_) => {
                return Ok(Resp::Status404_AResourceWithTheGivenKeyWasNotFound(
                    problem(
                        "Resource not found",
                        404,
                        format!("Resource key '{raw}' is not a valid key."),
                    ),
                ));
            }
        };

        // This endpoint deserialises RPA (JSON) resource content into a map.
        // Generic resources (e.g. Markdown) are not RPA, so — matching Camunda —
        // clients must use the binary content endpoint instead. Only existence
        // matters here (the response is always 406/404), so use the metadata-only
        // lookup and avoid loading the `content` blob.
        match self.store.resource_by_key_meta(key) {
            Some(_) => Ok(Resp::Status406_TheResourceExistsButIsNotAnRPAResource(
                problem(
                    "Resource is not an RPA resource",
                    406,
                    format!(
                        "Resource {key} is a generic resource; use the binary content endpoint."
                    ),
                ),
            )),
            None => Ok(Resp::Status404_AResourceWithTheGivenKeyWasNotFound(
                problem(
                    "Resource not found",
                    404,
                    format!("No resource with key {key}."),
                ),
            )),
        }
    }

    async fn search_resources_impl(
        &self,
        body: &Option<models::ResourceSearchQuery>,
    ) -> Result<apis::resource::SearchResourcesResponse, ()> {
        use apis::resource::SearchResourcesResponse as Resp;

        let filter = body.as_ref().and_then(|q| q.filter.as_ref());
        let rows = self.store.resources_meta();

        let mut matched: Vec<&readstore::ResourceMetaRow> = rows
            .iter()
            .filter(|row| match filter {
                None => true,
                Some(f) => {
                    query::match_resource_key(&f.resource_key, &row.resource_key.to_string())
                        && query::match_string(&f.resource_name, &row.resource_name)
                        && query::match_string(&f.resource_id, &row.resource_id)
                        && query::match_integer(&f.version, Some(row.version as i64))
                        && query::match_string_opt(&f.version_tag, row.version_tag.as_deref())
                        && f.tenant_id
                            .as_ref()
                            .is_none_or(|want| want == &row.tenant_id)
                }
            })
            .collect();

        let sort = query::sort_keys(
            body.as_ref().and_then(|q| q.sort.as_ref()),
            |r: &models::ResourceSearchQuerySortRequest| (r.field.clone(), r.order),
        );
        query::sort_items(
            &mut matched,
            &sort,
            |row, field| match field {
                "resourceId" => query::SortVal::Str(row.resource_id.clone()),
                "resourceName" => query::SortVal::Str(row.resource_name.clone()),
                "version" => query::SortVal::Num(row.version as i64),
                // `versionTag` is nullable; a null tag sorts as the empty string
                // (before any present tag ascending), matching how the read model
                // projects `versionTag: null`.
                "versionTag" => query::SortVal::Str(row.version_tag.clone().unwrap_or_default()),
                "resourceKey" => query::SortVal::Num(row.resource_key as i64),
                "tenantId" => query::SortVal::Str(row.tenant_id.clone()),
                _ => query::SortVal::Num(row.resource_key as i64),
            },
            |row| row.resource_key,
        );

        let sorted: Vec<(u64, &readstore::ResourceMetaRow)> = matched
            .into_iter()
            .map(|row| (row.resource_key, row))
            .collect();
        let page = query::paginate(sorted, body.as_ref().and_then(|q| q.page.as_ref()));
        let items: Vec<models::ResourceResult> =
            page.items.into_iter().map(resource_result).collect();

        Ok(Resp::Status200_TheResourceSearchResult(
            models::ResourceSearchQueryResult::new(page.response, items),
        ))
    }

    async fn search_process_instances_impl(
        &self,
        body: &Option<models::ProcessInstanceSearchQuery>,
    ) -> Result<apis::process_instance::SearchProcessInstancesResponse, ()> {
        use apis::process_instance::SearchProcessInstancesResponse as Resp;
        let filter = body.as_ref().and_then(|q| q.filter.as_ref());
        let instances = self.store.process_instances();

        // The `variables` filter constrains results to instances whose
        // process-scoped (root) variables match. Pre-index those variables by
        // instance only when a variable filter is actually present, so the
        // common (no variable-filter) path pays nothing for the extra scan.
        let variables_index: std::collections::HashMap<
            u64,
            std::collections::HashMap<String, String>,
        > = match filter {
            Some(f) if f.variables.as_ref().is_some_and(|v| !v.is_empty()) => {
                // Only the variable names referenced by the filter can affect
                // the match, so restrict the index to that set. This keeps the
                // scan a single pass while avoiding HashMap churn for unrelated
                // variable names in a large store.
                let requested: std::collections::HashSet<&str> = f
                    .variables
                    .as_ref()
                    .map(|v| v.iter().map(|entry| entry.name.as_str()).collect())
                    .unwrap_or_default();
                let mut idx: std::collections::HashMap<
                    u64,
                    std::collections::HashMap<String, String>,
                > = std::collections::HashMap::new();
                for v in self.store.variables() {
                    // Root-scope (process-instance) variables only: a variable
                    // held under a nested scope has `scope_key != instance_key`
                    // and is not a process-instance-level variable.
                    if v.scope_key == v.instance_key && requested.contains(v.name.as_str()) {
                        idx.entry(v.instance_key)
                            .or_default()
                            .insert(v.name, v.value);
                    }
                }
                idx
            }
            _ => std::collections::HashMap::new(),
        };

        let mut matched: Vec<&readstore::ProcessInstanceRow> = instances
            .iter()
            .filter(|inst| match filter {
                None => true,
                Some(f) => {
                    let state_str = process_instance_state_enum(inst.state).to_string();
                    query::match_process_instance_key(
                        &f.process_instance_key,
                        &inst.key.to_string(),
                    ) && query::match_process_definition_key(
                        &f.process_definition_key,
                        &inst.process_definition_key,
                    ) && query::match_string(&f.process_definition_id, &inst.process_definition_id)
                        && query::match_integer(
                            &f.process_definition_version,
                            Some(i64::from(inst.version)),
                        )
                        && query::match_process_instance_state(&f.state, &state_str)
                        && f.has_incident.is_none_or(|want| want == inst.has_incident)
                        && query::match_date_time_ms(&f.start_date, Some(inst.start_date_ms as i64))
                        // Nano does not yet project a process-instance completion
                        // timestamp, so an `endDate` filter matches against an
                        // absent value: range/equality operators correctly exclude
                        // (honest, not silently ignored) while `$exists: false`
                        // still matches.
                        && query::match_date_time_ms(&f.end_date, None)
                        && query::match_string_opt(&f.business_id, inst.business_id.as_deref())
                        // Call-activity hierarchy filters (C8 parity, issue
                        // #977): a bare parent key enumerates the direct children
                        // of that instance; `$exists:false` selects top-level
                        // instances. A top-level instance carries no parent, so
                        // its parent keys match against an absent value.
                        && query::match_process_instance_key_opt(
                            &f.parent_process_instance_key,
                            inst.parent_process_instance_key
                                .map(|k| k.to_string())
                                .as_deref(),
                        )
                        && query::match_element_instance_key_opt(
                            &f.parent_element_instance_key,
                            inst.parent_element_instance_key
                                .map(|k| k.to_string())
                                .as_deref(),
                        )
                        && match_instance_variables(
                            &f.variables,
                            variables_index.get(&inst.key),
                        )
                }
            })
            .collect();

        let sort = query::sort_keys(
            body.as_ref().and_then(|q| q.sort.as_ref()),
            |r: &models::ProcessInstanceSearchQuerySortRequest| (r.field.clone(), r.order),
        );
        query::sort_items(
            &mut matched,
            &sort,
            |inst, field| match field {
                "processDefinitionId" => query::SortVal::Str(inst.process_definition_id.clone()),
                "processDefinitionKey" => {
                    query::SortVal::Num(inst.process_definition_key.parse().unwrap_or(0))
                }
                "state" => query::SortVal::Str(process_instance_state_enum(inst.state).to_string()),
                "businessId" => query::SortVal::Str(inst.business_id.clone().unwrap_or_default()),
                _ => query::SortVal::Num(inst.key as i64),
            },
            |inst| inst.key,
        );

        let sorted: Vec<(u64, &readstore::ProcessInstanceRow)> =
            matched.into_iter().map(|inst| (inst.key, inst)).collect();
        let page = query::paginate(sorted, body.as_ref().and_then(|q| q.page.as_ref()));
        // Build result models only for the returned page, never the whole
        // (potentially very large) matched set. One memoised root resolver spans
        // the page so instances sharing a parent chain walk it once.
        let roots = readstore::RootResolver::new(|k| self.store.process_instance(k));
        let items: Vec<models::ProcessInstanceResult> = page
            .items
            .into_iter()
            .map(|inst| process_instance_result(inst, &roots))
            .collect();

        Ok(Resp::Status200_TheProcessInstanceSearchResult(
            models::ProcessInstanceSearchQueryResult::new(page.response, items),
        ))
    }

    /// Searches open message subscriptions (Zeebe `searchMessageSubscriptions`).
    ///
    /// Backed by the `message_subscriptions` read-model table, which retains only
    /// *open*, instance-scoped subscriptions (a running element instance parked on
    /// a message catch), dropped on correlate/cancel/terminate. Every retained row
    /// therefore surfaces with `state = CREATED` and `type = PROCESS_EVENT`;
    /// settled subscriptions and message-*start* (`START_EVENT`) subscriptions are
    /// not materialised and so are not returned. Process-definition attributes are
    /// resolved by joining each subscription's instance to `process_instances`.
    async fn search_message_subscriptions_impl(
        &self,
        body: &Option<models::MessageSubscriptionSearchQuery>,
    ) -> Result<apis::message_subscription::SearchMessageSubscriptionsResponse, ()> {
        use apis::message_subscription::SearchMessageSubscriptionsResponse as Resp;

        // Every open read-model subscription is a created, process-event catch.
        let state_str = models::MessageSubscriptionStateEnum::Created.to_string();
        let type_str = models::MessageSubscriptionTypeEnum::ProcessEvent.to_string();

        let filter = body.as_ref().and_then(|q| q.filter.as_ref());
        let subs = self.store.message_subscriptions();

        // Resolve process-definition attributes by joining to the owning instance.
        let instances = self.store.process_instances();
        let by_instance: std::collections::HashMap<u64, &readstore::ProcessInstanceRow> =
            instances.iter().map(|inst| (inst.key, inst)).collect();

        struct MsgSubEntry {
            subscription_key: u64,
            process_definition_id: String,
            process_definition_key: Option<String>,
            process_instance_key: u64,
            element_id: String,
            element_instance_key: u64,
            last_updated_ms: u64,
            message_name: String,
            correlation_key: String,
            process_definition_version: Option<i32>,
            /// The owning instance's business id (joined, like the definition
            /// attributes): the single source for both filter and result.
            business_id: Option<String>,
        }

        let entries: Vec<MsgSubEntry> = subs
            .into_iter()
            .filter_map(|sub| {
                // Skip subscriptions whose owning instance is not yet projected
                // (eventual consistency / shard ordering). Emitting a row with an
                // empty `processDefinitionId` and null definition metadata would be
                // malformed Zeebe-parity output; surfacing the subscription only
                // once its instance join resolves keeps definition attributes and
                // the subscription atomic, so a partially-populated row can never
                // escape.
                let inst = by_instance.get(&sub.instance_key)?;
                Some(MsgSubEntry {
                    subscription_key: sub.subscription_key,
                    process_definition_id: inst.process_definition_id.clone(),
                    process_definition_key: Some(inst.process_definition_key.clone()),
                    process_instance_key: sub.instance_key,
                    element_id: sub.element_id,
                    element_instance_key: sub.element_instance_key,
                    last_updated_ms: sub.created_at_ms,
                    message_name: sub.message_name,
                    correlation_key: sub.correlation_key,
                    process_definition_version: Some(inst.version),
                    business_id: sub.business_id,
                })
            })
            .collect();

        // All Zeebe `MessageSubscriptionFilter` fields are honoured. Fields Nano
        // does not yet project (`processDefinitionName`, `toolName`,
        // `inboundConnectorType`) are matched against an absent value, so an
        // equality/`$like` filter on them correctly yields no rows (rather than
        // being silently ignored) while `$exists: false` still matches.
        let mut matched: Vec<MsgSubEntry> = entries
            .into_iter()
            .filter(|e| match filter {
                None => true,
                Some(f) => {
                    query::match_message_subscription_key(
                        &f.message_subscription_key,
                        &e.subscription_key.to_string(),
                    ) && query::match_process_definition_key(
                        &f.process_definition_key,
                        e.process_definition_key.as_deref().unwrap_or(""),
                    ) && query::match_string(&f.process_definition_id, &e.process_definition_id)
                        && query::match_process_instance_key(
                            &f.process_instance_key,
                            &e.process_instance_key.to_string(),
                        )
                        && query::match_string(&f.element_id, &e.element_id)
                        && query::match_element_instance_key(
                            &f.element_instance_key,
                            &e.element_instance_key.to_string(),
                        )
                        && query::match_string(&f.message_name, &e.message_name)
                        && query::match_string(&f.correlation_key, &e.correlation_key)
                        && query::match_message_subscription_state(
                            &f.message_subscription_state,
                            &state_str,
                        )
                        && query::match_message_subscription_type(
                            &f.message_subscription_type,
                            &type_str,
                        )
                        && query::match_string(&f.tenant_id, "<default>")
                        && query::match_integer(
                            &f.process_definition_version,
                            e.process_definition_version.map(i64::from),
                        )
                        && query::match_date_time_ms(
                            &f.last_updated_date,
                            Some(e.last_updated_ms as i64),
                        )
                        && query::match_string_opt(&f.process_definition_name, None)
                        && query::match_string_opt(&f.tool_name, None)
                        && query::match_string_opt(&f.inbound_connector_type, None)
                        && query::match_string_opt(&f.business_id, e.business_id.as_deref())
                }
            })
            .collect();

        let sort = query::sort_keys(
            body.as_ref().and_then(|q| q.sort.as_ref()),
            |r: &models::MessageSubscriptionSearchQuerySortRequest| (r.field.clone(), r.order),
        );
        query::sort_items(
            &mut matched,
            &sort,
            |e, field| match field {
                "processDefinitionId" => query::SortVal::Str(e.process_definition_id.clone()),
                "processDefinitionKey" => query::SortVal::Num(
                    e.process_definition_key
                        .as_deref()
                        .and_then(|k| k.parse().ok())
                        .unwrap_or(0),
                ),
                "processDefinitionVersion" => {
                    query::SortVal::Num(e.process_definition_version.unwrap_or(0) as i64)
                }
                "processInstanceKey" => query::SortVal::Num(e.process_instance_key as i64),
                "elementId" => query::SortVal::Str(e.element_id.clone()),
                "elementInstanceKey" => query::SortVal::Num(e.element_instance_key as i64),
                "messageName" => query::SortVal::Str(e.message_name.clone()),
                "correlationKey" => query::SortVal::Str(e.correlation_key.clone()),
                "lastUpdatedDate" => query::SortVal::Num(e.last_updated_ms as i64),
                "businessId" => query::SortVal::Str(e.business_id.clone().unwrap_or_default()),
                _ => query::SortVal::Num(e.subscription_key as i64),
            },
            |e| e.subscription_key,
        );

        let sorted: Vec<(u64, MsgSubEntry)> = matched
            .into_iter()
            .map(|e| (e.subscription_key, e))
            .collect();
        let page = query::paginate(sorted, body.as_ref().and_then(|q| q.page.as_ref()));
        let items: Vec<models::MessageSubscriptionResult> = page
            .items
            .into_iter()
            .map(|e| {
                let last_updated = chrono::DateTime::<chrono::Utc>::from_timestamp_millis(
                    e.last_updated_ms as i64,
                )
                .unwrap_or_else(epoch);
                let business_id = nullable_business_id(e.business_id);
                // Named fields, not the positional `::new`: an upstream field
                // insertion must fail to compile, not silently shift arguments.
                models::MessageSubscriptionResult {
                    business_id,
                    message_subscription_key: models::MessageSubscriptionKey(
                        e.subscription_key.to_string(),
                    ),
                    process_definition_id: e.process_definition_id,
                    process_definition_key: match e.process_definition_key {
                        Some(k) => types::Nullable::Present(models::ProcessDefinitionKey(k)),
                        None => types::Nullable::Null,
                    },
                    process_instance_key: types::Nullable::Present(models::ProcessInstanceKey(
                        e.process_instance_key.to_string(),
                    )),
                    root_process_instance_key: types::Nullable::Null,
                    element_id: e.element_id,
                    element_instance_key: types::Nullable::Present(models::ElementInstanceKey(
                        e.element_instance_key.to_string(),
                    )),
                    message_subscription_state: models::MessageSubscriptionStateEnum::Created,
                    last_updated_date: last_updated,
                    message_name: e.message_name,
                    correlation_key: types::Nullable::Present(e.correlation_key),
                    message_subscription_type: models::MessageSubscriptionTypeEnum::ProcessEvent,
                    tool_properties: std::collections::HashMap::new(),
                    process_definition_name: types::Nullable::Null,
                    process_definition_version: match e.process_definition_version {
                        Some(v) => types::Nullable::Present(v),
                        None => types::Nullable::Null,
                    },
                    tool_name: types::Nullable::Null,
                    inbound_connector_type: types::Nullable::Null,
                    tenant_id: "<default>".to_string(),
                }
            })
            .collect();

        Ok(Resp::Status200_TheMessageSubscriptionSearchResult(
            models::MessageSubscriptionSearchQueryResult::new(page.response, items),
        ))
    }

    /// Searches correlated message subscriptions (Zeebe
    /// `searchCorrelatedMessageSubscriptions`).
    ///
    /// Backed by the `correlated_message_subscriptions` read-model history table,
    /// materialised from `MessageCorrelated`/`RemoteMessageCorrelation` events for
    /// instance-scoped subscriptions. Process-definition attributes are resolved by
    /// joining each correlation's instance to `process_instances`. Honours the Zeebe
    /// filter, sort and cursor-pagination contract.
    ///
    /// Limitation: only instance-scoped correlations are recorded (message-*start*
    /// correlations, which spawn a new instance, are not).
    async fn search_correlated_message_subscriptions_impl(
        &self,
        body: &Option<models::CorrelatedMessageSubscriptionSearchQuery>,
    ) -> Result<apis::message_subscription::SearchCorrelatedMessageSubscriptionsResponse, ()> {
        use apis::message_subscription::SearchCorrelatedMessageSubscriptionsResponse as Resp;

        let filter = body.as_ref().and_then(|q| q.filter.as_ref());
        let rows = self.store.correlated_message_subscriptions();

        let instances = self.store.process_instances();
        let by_instance: std::collections::HashMap<u64, &readstore::ProcessInstanceRow> =
            instances.iter().map(|inst| (inst.key, inst)).collect();

        struct CorrEntry {
            message_key: u64,
            subscription_key: u64,
            process_definition_id: String,
            process_definition_key: Option<String>,
            process_instance_key: u64,
            element_id: String,
            element_instance_key: u64,
            message_name: String,
            correlation_key: String,
            correlation_time_ms: u64,
            partition_id: i32,
            /// The owning instance's business id (joined): filter + result source.
            business_id: Option<String>,
        }

        let entries: Vec<CorrEntry> = rows
            .into_iter()
            .filter_map(|row| {
                // Skip correlations whose owning instance is not yet projected
                // (eventual consistency / shard ordering). `processDefinitionId`
                // and `processDefinitionKey` are required, non-nullable fields in
                // the correlated-subscription result schema, so emitting a row with
                // an empty definition id / key would be malformed Zeebe-parity
                // output. Surfacing the correlation only once its instance join
                // resolves keeps the row atomic.
                let inst = by_instance.get(&row.instance_key)?;
                Some(CorrEntry {
                    message_key: row.message_key,
                    subscription_key: row.subscription_key,
                    process_definition_id: inst.process_definition_id.clone(),
                    process_definition_key: Some(inst.process_definition_key.clone()),
                    process_instance_key: row.instance_key,
                    element_id: row.element_id,
                    element_instance_key: row.element_instance_key,
                    message_name: row.message_name,
                    correlation_key: row.correlation_key,
                    correlation_time_ms: row.correlation_time_ms,
                    partition_id: row.partition_id,
                    business_id: row.business_id,
                })
            })
            .collect();

        // Every Zeebe `CorrelatedMessageSubscriptionFilter` field is honoured,
        // including `partitionId` (Integer) and `correlationTime` (DateTime).
        let mut matched: Vec<CorrEntry> = entries
            .into_iter()
            .filter(|e| match filter {
                None => true,
                Some(f) => {
                    query::match_string(&f.correlation_key, &e.correlation_key)
                        && query::match_integer(&f.partition_id, Some(i64::from(e.partition_id)))
                        && query::match_string_opt(&f.business_id, e.business_id.as_deref())
                        && query::match_date_time_ms(
                            &f.correlation_time,
                            Some(e.correlation_time_ms as i64),
                        )
                        && query::match_string(&f.element_id, &e.element_id)
                        && query::match_element_instance_key(
                            &f.element_instance_key,
                            &e.element_instance_key.to_string(),
                        )
                        && query::match_basic_string(&f.message_key, &e.message_key.to_string())
                        && query::match_string(&f.message_name, &e.message_name)
                        && query::match_string(&f.process_definition_id, &e.process_definition_id)
                        && query::match_process_definition_key(
                            &f.process_definition_key,
                            e.process_definition_key.as_deref().unwrap_or(""),
                        )
                        && query::match_process_instance_key(
                            &f.process_instance_key,
                            &e.process_instance_key.to_string(),
                        )
                        && query::match_message_subscription_key(
                            &f.subscription_key,
                            &e.subscription_key.to_string(),
                        )
                        && query::match_string(&f.tenant_id, "<default>")
                }
            })
            .collect();

        let sort = query::sort_keys(
            body.as_ref().and_then(|q| q.sort.as_ref()),
            |r: &models::CorrelatedMessageSubscriptionSearchQuerySortRequest| {
                (r.field.clone(), r.order)
            },
        );
        query::sort_items(
            &mut matched,
            &sort,
            |e, field| match field {
                "correlationKey" => query::SortVal::Str(e.correlation_key.clone()),
                "correlationTime" => query::SortVal::Num(e.correlation_time_ms as i64),
                "elementId" => query::SortVal::Str(e.element_id.clone()),
                "elementInstanceKey" => query::SortVal::Num(e.element_instance_key as i64),
                "messageName" => query::SortVal::Str(e.message_name.clone()),
                "partitionId" => query::SortVal::Num(e.partition_id as i64),
                "processDefinitionId" => query::SortVal::Str(e.process_definition_id.clone()),
                "processDefinitionKey" => query::SortVal::Num(
                    e.process_definition_key
                        .as_deref()
                        .and_then(|k| k.parse().ok())
                        .unwrap_or(0),
                ),
                "processInstanceKey" => query::SortVal::Num(e.process_instance_key as i64),
                "subscriptionKey" => query::SortVal::Num(e.subscription_key as i64),
                "tenantId" => query::SortVal::Str("<default>".to_string()),
                "businessId" => query::SortVal::Str(e.business_id.clone().unwrap_or_default()),
                _ => query::SortVal::Num(e.message_key as i64),
            },
            // A single published message can fan out to multiple subscriptions,
            // and a non-interrupting boundary subscription correlates repeatedly,
            // so neither key is unique on its own. The composite PK
            // (message_key, subscription_key) is, so tiebreak and page on the pair
            // to keep cursor paging unambiguous and the order stable.
            |e| (e.message_key, e.subscription_key),
        );

        let sorted: Vec<((u64, u64), CorrEntry)> = matched
            .into_iter()
            .map(|e| ((e.message_key, e.subscription_key), e))
            .collect();
        let page = query::paginate(sorted, body.as_ref().and_then(|q| q.page.as_ref()));
        let items: Vec<models::CorrelatedMessageSubscriptionResult> = page
            .items
            .into_iter()
            .map(|e| {
                let correlation_time = chrono::DateTime::<chrono::Utc>::from_timestamp_millis(
                    e.correlation_time_ms as i64,
                )
                .unwrap_or_else(epoch);
                models::CorrelatedMessageSubscriptionResult {
                    business_id: nullable_business_id(e.business_id.clone()),
                    correlation_key: types::Nullable::Present(e.correlation_key),
                    correlation_time,
                    element_id: e.element_id,
                    element_instance_key: types::Nullable::Present(models::ElementInstanceKey(
                        e.element_instance_key.to_string(),
                    )),
                    message_key: models::MessageKey(e.message_key.to_string()),
                    message_name: e.message_name,
                    partition_id: e.partition_id,
                    process_definition_id: e.process_definition_id,
                    process_definition_key: models::ProcessDefinitionKey(
                        e.process_definition_key.unwrap_or_default(),
                    ),
                    process_instance_key: models::ProcessInstanceKey(
                        e.process_instance_key.to_string(),
                    ),
                    root_process_instance_key: types::Nullable::Null,
                    subscription_key: models::MessageSubscriptionKey(
                        e.subscription_key.to_string(),
                    ),
                    tenant_id: "<default>".to_string(),
                }
            })
            .collect();

        Ok(
            Resp::Status200_TheCorrelatedMessageSubscriptionsSearchResult(
                models::CorrelatedMessageSubscriptionSearchQueryResult::new(page.response, items),
            ),
        )
    }

    /// The CURRENT `businessId` of a process instance (Camunda 8.10). Test-only:
    /// artifact results surface the id snapshotted on their own row at
    /// creation, never this live value (#1295 review).
    #[cfg(test)]
    fn business_id_of(&self, process_instance_key: u64) -> types::Nullable<String> {
        nullable_business_id(
            self.store
                .process_instance(process_instance_key)
                .and_then(|pi| pi.business_id),
        )
    }

    async fn search_jobs_impl(
        &self,
        body: &Option<models::JobSearchQuery>,
    ) -> Result<apis::job::SearchJobsResponse, ()> {
        use apis::job::SearchJobsResponse as Resp;

        let filter = body.as_ref().and_then(|q| q.filter.as_ref());
        let jobs = self.store.jobs();

        let mut matched: Vec<&readstore::JobRow> = jobs
            .iter()
            .filter(|job| match filter {
                None => true,
                Some(f) => {
                    query::match_job_key(&f.job_key, &job.key.to_string())
                        && query::match_process_instance_key(
                            &f.process_instance_key,
                            &job.instance_key.to_string(),
                        )
                        && query::match_process_definition_key(
                            &f.process_definition_key,
                            &job.process_definition_key,
                        )
                        && query::match_element_instance_key(
                            &f.element_instance_key,
                            &job.element_instance_key.to_string(),
                        )
                        && query::match_string(&f.r_type, &job.job_type)
                        && query::match_string(&f.element_id, &job.element_id)
                        && query::match_job_state(&f.state, &job_state_enum(job.state).to_string())
                        && query::match_string_opt(&f.error_message, job.error_message.as_deref())
                        && query::match_string_opt(&f.error_code, job.error_code.as_deref())
                        && f.has_failed_with_retries_left
                            .is_none_or(|want| want == job.has_failed_with_retries_left)
                }
            })
            .collect();

        let sort = query::sort_keys(
            body.as_ref().and_then(|q| q.sort.as_ref()),
            |r: &models::JobSearchQuerySortRequest| (r.field.clone(), r.order),
        );
        query::sort_items(
            &mut matched,
            &sort,
            |job, field| match field {
                "processInstanceKey" => query::SortVal::Num(job.instance_key as i64),
                "elementId" => query::SortVal::Str(job.element_id.clone()),
                "type" => query::SortVal::Str(job.job_type.clone()),
                "state" => query::SortVal::Str(job_state_enum(job.state).to_string()),
                "retries" => query::SortVal::Num(job.retries as i64),
                _ => query::SortVal::Num(job.key as i64),
            },
            |job| job.key,
        );

        let sorted: Vec<(u64, &readstore::JobRow)> =
            matched.into_iter().map(|job| (job.key, job)).collect();
        let page = query::paginate(sorted, body.as_ref().and_then(|q| q.page.as_ref()));
        let items: Vec<models::JobSearchResult> =
            page.items.into_iter().map(job_search_result).collect();

        Ok(Resp::Status200_TheJobSearchResult(
            models::JobSearchQueryResult::new(page.response, items),
        ))
    }

    async fn search_element_instances_impl(
        &self,
        body: &Option<models::ElementInstanceSearchQuery>,
    ) -> Result<apis::element_instance::SearchElementInstancesResponse, ()> {
        use apis::element_instance::SearchElementInstancesResponse as Resp;

        let filter = body.as_ref().and_then(|q| q.filter.as_ref());
        let rows = self.store.element_instances();

        let mut matched: Vec<&readstore::ElementInstanceRow> = rows
            .iter()
            .filter(|ei| match filter {
                None => true,
                Some(f) => match_element_instance_filter(ei, f),
            })
            .collect();

        let sort = query::sort_keys(
            body.as_ref().and_then(|q| q.sort.as_ref()),
            |r: &models::ElementInstanceSearchQuerySortRequest| (r.field.clone(), r.order),
        );
        query::sort_items(
            &mut matched,
            &sort,
            |ei, field| match field {
                "processInstanceKey" => query::SortVal::Num(ei.instance_key as i64),
                "processDefinitionKey" => {
                    query::SortVal::Num(ei.process_definition_key.parse().unwrap_or(0))
                }
                "processDefinitionId" => query::SortVal::Str(ei.process_definition_id.clone()),
                "elementId" => query::SortVal::Str(ei.element_id.clone()),
                "elementName" => query::SortVal::Str(
                    ei.element_name
                        .clone()
                        .unwrap_or_else(|| ei.element_id.clone()),
                ),
                "type" => query::SortVal::Str(ei.element_type.clone()),
                "state" => query::SortVal::Str(element_instance_state_enum(ei.state).to_string()),
                "startDate" => query::SortVal::Num(ei.start_date_ms as i64),
                "endDate" => query::SortVal::Num(ei.end_date_ms.unwrap_or(0) as i64),
                _ => query::SortVal::Num(ei.element_instance_key as i64),
            },
            |ei| ei.element_instance_key,
        );

        let sorted: Vec<(u64, &readstore::ElementInstanceRow)> = matched
            .into_iter()
            .map(|ei| (ei.element_instance_key, ei))
            .collect();
        let page = query::paginate(sorted, body.as_ref().and_then(|q| q.page.as_ref()));
        // One memoised root resolver spans the page so every element of the same
        // process instance resolves that instance's root once, not per element.
        let roots = readstore::RootResolver::new(|k| self.store.process_instance(k));
        let items: Vec<models::ElementInstanceResult> = page
            .items
            .into_iter()
            .map(|row| element_instance_result(row, &roots))
            .collect();

        Ok(Resp::Status200_TheElementInstanceSearchResult(
            models::ElementInstanceSearchQueryResult::new(page.response, items),
        ))
    }

    async fn get_element_instance_impl(
        &self,
        path_params: &models::GetElementInstancePathParams,
    ) -> Result<apis::element_instance::GetElementInstanceResponse, ()> {
        use apis::element_instance::GetElementInstanceResponse as Resp;

        let key: u64 = match path_params.element_instance_key.parse() {
            Ok(k) => k,
            Err(_) => {
                return Ok(
                    Resp::Status404_TheElementInstanceWithTheGivenKeyWasNotFound(problem(
                        "Element instance not found",
                        404,
                        format!(
                            "Element instance key '{}' is not a valid key.",
                            path_params.element_instance_key
                        ),
                    )),
                );
            }
        };

        let result = self.store.element_instance(key);
        if result.is_none()
            && let Some(node) = self.read_route(key)
        {
            let (status, body) = self
                .forward_get(node, crate::falcon::ReadKind::ElementInstance, key)
                .await;
            return Ok(match (status, body) {
                (200, Some(b)) => match serde_json::from_value(b) {
                    Ok(r) => Resp::Status200_TheElementInstanceIsSuccessfullyReturned(r),
                    Err(e) => Resp::Status500_AnInternalErrorOccurredWhileProcessingTheRequest(
                        problem("Peer error", 500, e.to_string()),
                    ),
                },
                (404, _) => Resp::Status404_TheElementInstanceWithTheGivenKeyWasNotFound(problem(
                    "Element instance not found",
                    404,
                    format!("No element instance with key {key}."),
                )),
                (s, _) => {
                    Resp::Status500_AnInternalErrorOccurredWhileProcessingTheRequest(problem(
                        "Peer error",
                        500,
                        format!("peer node {node} returned status {s}"),
                    ))
                }
            });
        }
        match result {
            Some(row) => Ok(Resp::Status200_TheElementInstanceIsSuccessfullyReturned(
                element_instance_result(
                    &row,
                    &readstore::RootResolver::new(|k| self.store.process_instance(k)),
                ),
            )),
            None => Ok(
                Resp::Status404_TheElementInstanceWithTheGivenKeyWasNotFound(problem(
                    "Element instance not found",
                    404,
                    format!("No element instance with key {key}."),
                )),
            ),
        }
    }

    /// `POST /v2/agent-instances` — create an engine-native agent instance on the
    /// AI-Agent element instance named by the request. Wires to the S3
    /// [`Command::CreateAgentInstance`] processor; the created instance's dedicated
    /// key is read back from the emitted `AgentInstanceCreated` event.
    async fn create_agent_instance_impl(
        &self,
        body: &models::AgentInstanceCreationRequest,
    ) -> Result<apis::agent_instance::CreateAgentInstanceResponse, ()> {
        // Client-edge entry (the generated trait dispatches here): count a
        // deprecated legacy lease-name use against the migration metric.
        self.create_agent_instance_inner(body, true).await
    }

    /// Peer-side entry for a request forwarded from another node
    /// ([`agent_instance_forwarded`]). The forwarding gateway already counted any
    /// legacy lease-name use at the client edge, so the owning peer reconciles
    /// *without* counting — otherwise every forwarded request that carries the
    /// legacy `jobLease` spelling (kept for mixed-version peers) is counted twice
    /// (#1283).
    async fn create_agent_instance_forwarded_impl(
        &self,
        body: &models::AgentInstanceCreationRequest,
    ) -> Result<apis::agent_instance::CreateAgentInstanceResponse, ()> {
        self.create_agent_instance_inner(body, false).await
    }

    async fn create_agent_instance_inner(
        &self,
        body: &models::AgentInstanceCreationRequest,
        count_legacy: bool,
    ) -> Result<apis::agent_instance::CreateAgentInstanceResponse, ()> {
        use apis::agent_instance::CreateAgentInstanceResponse as Resp;

        let element_instance_key: Key = match body.element_instance_key.0.parse() {
            Ok(k) => k,
            Err(_) => {
                return Ok(Resp::Status400_TheProvidedDataIsNotValid(problem(
                    "Invalid element instance key",
                    400,
                    format!(
                        "Element instance key '{}' is not a valid key.",
                        body.element_instance_key.0
                    ),
                )));
            }
        };

        let job_lease_token = match reconcile_lease_token_counted(
            body.job_lease_token.clone(),
            body.job_lease.clone(),
            count_legacy,
        ) {
            Ok(token) => token,
            Err(ConflictingLeaseTokens) => {
                return Ok(Resp::Status400_TheProvidedDataIsNotValid(problem(
                    "Invalid data",
                    400,
                    CONFLICTING_LEASE_TOKENS_DETAIL.to_string(),
                )));
            }
        };
        let (job_key, job_lease) = match parse_agent_job_attribution(
            Some(body.job_key.0.as_str()),
            job_lease_token.as_deref(),
        ) {
            Ok(attribution) => attribution,
            Err((title, detail)) => {
                return Ok(Resp::Status400_TheProvidedDataIsNotValid(problem(
                    title, 400, detail,
                )));
            }
        };
        if element_instance_key == 0 || body.history.is_empty() {
            return Ok(Resp::Status400_TheProvidedDataIsNotValid(problem(
                "Invalid agent creation",
                400,
                "A positive elementInstanceKey and nonempty history are required.".into(),
            )));
        }
        if let Err(detail) = validate_agent_history(&body.history) {
            return Ok(Resp::Status400_TheProvidedDataIsNotValid(problem(
                "Invalid agent history",
                400,
                detail,
            )));
        }
        if let Some(node) = self.route_by_leader(element_instance_key) {
            // Forward the resolved lease token under BOTH the canonical
            // `jobLeaseToken` and the deprecated legacy `jobLease` spelling. The
            // legacy spelling keeps a mixed-version rolling upgrade working: a
            // newer gateway can route to an older peer whose request model only
            // knows the pre-rename `jobLease`, which would otherwise reject the
            // forwarded request as missing its lease. The owning peer reconciles
            // via `create_agent_instance_forwarded_impl` (count = false), so
            // carrying the legacy spelling does not double-count the migration
            // metric — the gateway already counted the client's use above (#1283).
            let mut forwarded_body = body.clone();
            forwarded_body.job_lease_token = job_lease_token.clone();
            forwarded_body.job_lease = job_lease_token.clone();
            let forwarded = self
                .forward_agent_request(node, None, &forwarded_body)
                .await;
            return Ok(match forwarded {
                Ok(response) => response,
                Err((status, detail)) => agent_create_http_error(status, detail),
            });
        }
        let history: Vec<_> = body
            .history
            .iter()
            .map(|item| agent_history_turn_from(item, job_key, &job_lease))
            .collect();
        let submitted_ids = history
            .iter()
            .map(|turn| turn.history_item_id.clone().unwrap_or_default())
            .collect();
        let command = Command::CreateAgentInstance {
            element_instance_key,
            job_key,
            job_lease,
            definition: Default::default(),
            limits: None,
            history,
        };

        let outcome = self
            .apply_partition_command(element_instance_key, command)
            .await;
        match outcome {
            Ok((events, commit)) => {
                commit.wait().await;
                let agent_instance_key = events.iter().find_map(|e| match e {
                    Event::AgentInstanceCreated { agent_instance, .. } => {
                        Some(agent_instance.agent_instance_key)
                    }
                    _ => None,
                });
                let created_history =
                    created_history_from_events(&events, submitted_ids).ok_or(())?;
                match agent_instance_key {
                    Some(key) => Ok(Resp::Status200_TheAgentInstanceWasCreated(
                        models::AgentInstanceCreationResult::new(
                            models::AgentInstanceKey(key.to_string()),
                            created_history,
                        ),
                    )),
                    None => Ok(
                        Resp::Status500_AnInternalErrorOccurredWhileProcessingTheRequest(problem(
                            "Agent instance not created",
                            500,
                            "The create command emitted no AgentInstanceCreated event.".to_string(),
                        )),
                    ),
                }
            }
            Err((status, detail)) => Ok(agent_create_http_error(status, detail)),
        }
    }

    /// `GET /v2/agent-instances/{agentInstanceKey}` — return a single agent
    /// instance from the S4 read model, or 404 when unknown.
    async fn get_agent_instance_impl(
        &self,
        path_params: &models::GetAgentInstancePathParams,
    ) -> Result<apis::agent_instance::GetAgentInstanceResponse, ()> {
        use apis::agent_instance::GetAgentInstanceResponse as Resp;

        let key: Key = match path_params.agent_instance_key.parse() {
            Ok(k) if k > 0 => k,
            _ => {
                return Ok(Resp::Status400_TheProvidedDataIsNotValid(problem(
                    "Invalid agent instance key",
                    400,
                    format!(
                        "Agent instance key '{}' is not a valid key.",
                        path_params.agent_instance_key
                    ),
                )));
            }
        };

        match self.store.try_agent_instance(key).map_err(|_| ())? {
            Some(row) => Ok(Resp::Status200_TheAgentInstanceIsSuccessfullyReturned(
                agent_instance_result(&row).map_err(|_| ())?,
            )),
            None => Ok(Resp::Status404_TheAgentInstanceWithTheGivenKeyWasNotFound(
                problem(
                    "Agent instance not found",
                    404,
                    format!("No agent instance with key {key}."),
                ),
            )),
        }
    }

    /// `PATCH /v2/agent-instances/{agentInstanceKey}` — advance an agent
    /// instance's status and append a batch of history turns. Wires to the S3
    /// [`Command::UpdateAgentInstance`] processor; the ownership fields the 8.10
    /// request omits are resolved on the engine thread against primary state, and
    /// the created history keys are read back from the emitted events.
    async fn update_agent_instance_impl(
        &self,
        path_params: &models::UpdateAgentInstancePathParams,
        body: &models::AgentInstanceUpdateRequest,
    ) -> Result<apis::agent_instance::UpdateAgentInstanceResponse, ()> {
        // Client-edge entry: count a deprecated legacy lease-name use.
        self.update_agent_instance_inner(path_params, body, true)
            .await
    }

    /// Peer-side entry for a forwarded update ([`agent_instance_forwarded`]).
    /// Reconciles without counting — the forwarding gateway already counted the
    /// client's legacy lease-name use (#1283).
    async fn update_agent_instance_forwarded_impl(
        &self,
        path_params: &models::UpdateAgentInstancePathParams,
        body: &models::AgentInstanceUpdateRequest,
    ) -> Result<apis::agent_instance::UpdateAgentInstanceResponse, ()> {
        self.update_agent_instance_inner(path_params, body, false)
            .await
    }

    async fn update_agent_instance_inner(
        &self,
        path_params: &models::UpdateAgentInstancePathParams,
        body: &models::AgentInstanceUpdateRequest,
        count_legacy: bool,
    ) -> Result<apis::agent_instance::UpdateAgentInstanceResponse, ()> {
        use apis::agent_instance::UpdateAgentInstanceResponse as Resp;

        let agent_instance_key: Key = match path_params.agent_instance_key.parse() {
            Ok(k) => k,
            Err(_) => {
                return Ok(Resp::Status400_TheProvidedDataIsNotValid(problem(
                    "Invalid agent instance key",
                    400,
                    format!(
                        "Agent instance key '{}' is not a valid key.",
                        path_params.agent_instance_key
                    ),
                )));
            }
        };
        let element_instance_key: Key = match body.element_instance_key.0.parse() {
            Ok(k) => k,
            Err(_) => {
                return Ok(Resp::Status400_TheProvidedDataIsNotValid(problem(
                    "Invalid element instance key",
                    400,
                    format!(
                        "Element instance key '{}' is not a valid key.",
                        body.element_instance_key.0
                    ),
                )));
            }
        };

        let job_lease_token = match reconcile_lease_token_counted(
            body.job_lease_token.clone(),
            body.job_lease.clone(),
            count_legacy,
        ) {
            Ok(token) => token,
            Err(ConflictingLeaseTokens) => {
                return Ok(Resp::Status400_TheProvidedDataIsNotValid(problem(
                    "Invalid data",
                    400,
                    CONFLICTING_LEASE_TOKENS_DETAIL.to_string(),
                )));
            }
        };
        let (job_key, job_lease) = match parse_agent_job_attribution(
            Some(body.job_key.0.as_str()),
            job_lease_token.as_deref(),
        ) {
            Ok(attribution) => attribution,
            Err((title, detail)) => {
                return Ok(Resp::Status400_TheProvidedDataIsNotValid(problem(
                    title, 400, detail,
                )));
            }
        };
        if element_instance_key == 0 || agent_instance_key == 0 {
            return Ok(Resp::Status400_TheProvidedDataIsNotValid(problem(
                "Invalid agent key",
                400,
                "Agent and element instance keys must be positive.".into(),
            )));
        }
        if let Some(node) = self.route_by_leader(agent_instance_key) {
            // Forward the resolved lease token under BOTH spellings — canonical
            // `jobLeaseToken` and the deprecated legacy `jobLease` — so a
            // mixed-version rolling upgrade keeps working (an older peer only
            // knows the pre-rename `jobLease`). The owning peer reconciles via
            // `update_agent_instance_forwarded_impl` (count = false), so the
            // legacy spelling is not double-counted — the gateway already counted
            // the client's use above (#1283).
            let mut forwarded_body = body.clone();
            forwarded_body.job_lease_token = job_lease_token.clone();
            forwarded_body.job_lease = job_lease_token.clone();
            let forwarded = self
                .forward_agent_request(node, Some(agent_instance_key.to_string()), &forwarded_body)
                .await;
            return Ok(match forwarded {
                Ok(response) => response,
                Err((status, detail)) => agent_update_http_error(status, detail),
            });
        }
        let status = body.status.map(agent_update_status);
        if let Some(items) = present(&body.history)
            && let Err(detail) = validate_agent_history(items)
        {
            return Ok(Resp::Status400_TheProvidedDataIsNotValid(problem(
                "Invalid agent history",
                400,
                detail,
            )));
        }
        let history: Vec<agent_model::AgentHistoryTurn> = match &body.history {
            Some(types::Nullable::Present(items)) => items
                .iter()
                .map(|i| agent_history_turn_from(i, job_key, &job_lease))
                .collect(),
            _ => Vec::new(),
        };
        let submitted_ids: Vec<String> = history
            .iter()
            .map(|t| t.history_item_id.clone().unwrap_or_default())
            .collect();

        let Some(handle) = self.engine_handle_for(partition_of(agent_instance_key)) else {
            return Ok(agent_update_http_error(
                404,
                "Agent instance partition not found.".into(),
            ));
        };
        let command = handle
            .with(move |engine| {
                let (element_id, process_instance_key) = engine
                    .agent_instance_ownership(agent_instance_key)
                    .ok_or(EngineError::AgentInstanceNotFound { agent_instance_key })?;
                let command = Command::UpdateAgentInstance {
                    agent_instance_key,
                    element_instance_key,
                    element_id,
                    process_instance_key,
                    job_key,
                    job_lease,
                    status,
                    metrics: Default::default(),
                    tools: None,
                    history,
                };
                Ok(command)
            })
            .await;
        let command = match command {
            Ok(command) => command,
            Err(error) => {
                let (status, detail) = crate::raft::engine_error_status(&error);
                return Ok(agent_update_http_error(status, detail));
            }
        };
        let outcome = self
            .apply_partition_command(agent_instance_key, command)
            .await;

        match outcome {
            Ok((events, commit)) => {
                commit.wait().await;
                // Correlate each emitted AgentHistoryCreated to its submitted item
                // in request order; the processor emits them in submission order.
                let created_history = match created_history_from_events(&events, submitted_ids) {
                    Some(v) => v,
                    // No emitted event correlates to some submitted item: the
                    // processor produced fewer AgentHistoryCreated events than
                    // submitted turns. Returning a synthetic "0" key would 200
                    // with a meaningless key, so fail the request instead.
                    None => {
                        return Ok(
                            Resp::Status500_AnInternalErrorOccurredWhileProcessingTheRequest(
                                problem(
                                    "Agent instance update incomplete",
                                    500,
                                    "The update emitted fewer history events than submitted \
                                     turns; no key exists for at least one submitted item."
                                        .to_string(),
                                ),
                            ),
                        );
                    }
                };
                Ok(Resp::Status200_TheAgentInstanceWasUpdatedSuccessfully(
                    models::AgentInstanceUpdateResult::new(created_history),
                ))
            }
            Err((status, detail)) => Ok(agent_update_http_error(status, detail)),
        }
    }

    /// Applies an instance-less command that mints its own key (a standalone
    /// decision evaluation) on a partition chosen like a create. Raft mode
    /// proposes it through a partition this node LEADS (never a static-local
    /// follower), so an acknowledged write is replicated; a node leading nothing
    /// sheds a retryable 503. Without Raft it applies on a local partition and
    /// awaits durability.
    async fn apply_create_command(
        &self,
        command: Command,
    ) -> Result<Arc<Vec<Event>>, (u16, String)> {
        if self.raft.is_empty() {
            let Some(handle) = self.engine.try_for_create() else {
                return Err((500, "this node hosts no engine partition".to_string()));
            };
            let (events, commit) = handle
                .with(move |journal| journal.apply_command_at(command, now_millis()))
                .await
                .map_err(|error| crate::raft::engine_error_status(&error))?;
            commit.wait().await;
            return Ok(events);
        }
        let led: Vec<u64> = self
            .led_partitions()
            .into_iter()
            .filter(|&p| !self.handoff_write_gated(p))
            .collect();
        let Some(p) = self.engine.for_create_among(&led) else {
            return Err((503, "this node leads no partition; retry".to_string()));
        };
        let Some(part) = self.raft.get(p) else {
            return Err((500, format!("partition {p} has no Raft group")));
        };
        let response = part
            .propose_result(command, now_millis())
            .await
            .map_err(|e| match e {
                // A leadership race (ForwardToLeader while the batched write was
                // queued) is retryable, not an internal fault. #1306.
                crate::raft::ProposeError::Leader => {
                    (503, format!("partition {p} leader unavailable; retry"))
                }
                other => (500, other.to_string()),
            })?;
        if let Some((status, message)) = response.error {
            return Err((status, message));
        }
        Ok(Arc::new(response.events))
    }

    /// Applies `command` on the partition owning `key` and returns its events +
    /// a durable-commit barrier: through that partition's Raft leader when Raft
    /// is enabled (so the write is replicated before it is acknowledged), else
    /// directly on the local engine actor.
    ///
    /// This is THE single funnel for durable by-key REST/operator mutations —
    /// the `no_direct_engine_apply_in_handlers` guard test (#1306) forbids a
    /// handler from calling `engine.apply_command_at` itself, because a direct
    /// local apply under Raft never enters the replicated log and a failover
    /// silently loses the write (the #1305 defect class). Both paths map an
    /// engine rejection through [`crate::raft::engine_error_status`] and drive
    /// the command's cross-partition subscription routing exactly ONCE, so a
    /// caller cannot tell whether Raft was enabled.
    async fn apply_partition_command(
        &self,
        key: Key,
        command: Command,
    ) -> Result<(Arc<Vec<Event>>, Commit), (u16, String)> {
        if !self.raft.is_empty() {
            // `propose_partition_command` already awaits the durable barrier and
            // drives routing / job-sojourn / ad-hoc side effects on the replicated
            // events, so callers must NOT repeat them. `false`: this generic funnel
            // must not record the stream-completion diagnostic (#1306).
            return self.propose_partition_command(key, command, false).await;
        }
        let (events, commit) = self
            .engine
            .by_key(key)
            .with(move |journal| journal.apply_command_at(command, now_millis()))
            .await
            .map_err(|error| crate::raft::engine_error_status(&error))?;
        // Mirror the Raft path: wait for durability, then route any
        // cross-partition subscription follow-ups the command produced and record
        // the same committed-event telemetry (`propose_partition_command` drives
        // routing / job-sojourn / ad-hoc metrics on the replicated events). Doing
        // it here (not in each caller) keeps the side effects single-sourced and
        // prevents the double-count a per-handler repetition would cause under
        // Raft. The barrier is awaited here, so — like the Raft path — a ready
        // barrier is handed back and a caller's own `commit.wait()` is a harmless
        // no-op.
        commit.wait().await;
        self.spawn_routing_if_needed(&events);
        self.observe_job_sojourn(&events, now_millis());
        self.record_adhoc_events(&events);
        Ok((events, Commit::ready()))
    }

    /// The non-Raft (single-node) fallback for the job/stream mutation handlers:
    /// apply `command` directly on the owning engine actor and return the raw
    /// [`Journal::apply_command_at`] outcome. This is the ONLY place those
    /// handlers may apply on the engine — it exists so the
    /// `no_direct_engine_apply_guard` can confine their direct apply to this one
    /// small, allowlisted helper instead of trusting each whole handler body.
    /// Under Raft the handlers take the replicated `propose_*` path and never
    /// reach here, so this fallback runs only when Raft is disabled (where a
    /// local apply is correct and durable). #1306.
    ///
    /// Returns the raw outcome (no routing / sojourn / ad-hoc side effects and
    /// no durability wait): each caller keeps its own bespoke post-apply
    /// handling, exactly as before.
    async fn apply_job_command_direct(
        &self,
        job_key: Key,
        command: Command,
    ) -> Result<(Arc<Vec<Event>>, Commit), nanobpmn_engine_core::EngineError> {
        self.apply_job_command_direct_with(job_key, command, |_| ())
            .await
            .1
    }

    /// [`apply_job_command_direct`](Self::apply_job_command_direct) with a
    /// pre-apply hook run on the engine thread just before the command applies
    /// (the REST complete/fail/throw paths use it to capture the job's
    /// type/worker for statistics *before* the apply drops the activation).
    /// Keeping the apply itself inside this one helper is what lets the
    /// `no_direct_engine_apply_guard` confine the job/stream handlers' direct
    /// apply to the non-Raft fallback. #1306.
    async fn apply_job_command_direct_with<M>(
        &self,
        job_key: Key,
        command: Command,
        pre_apply: impl FnOnce(&mut Journal) -> M + Send + 'static,
    ) -> (
        M,
        Result<(Arc<Vec<Event>>, Commit), nanobpmn_engine_core::EngineError>,
    )
    where
        M: Send + 'static,
    {
        self.engine
            .by_key(job_key)
            .with(move |journal| {
                let meta = pre_apply(journal);
                (meta, journal.apply_command_at(command, now_millis()))
            })
            .await
    }

    async fn forward_agent_request<T: serde::Serialize, R: serde::de::DeserializeOwned>(
        &self,
        node: u32,
        agent_instance_key: Option<String>,
        body: &T,
    ) -> Result<R, (u16, String)> {
        let body = serde_json::to_value(body).map_err(|error| (500, error.to_string()))?;
        let response = self
            .peer_link(node)
            .await?
            .forward_agent_instance(agent_instance_key, body)
            .await
            .map_err(|error| (502, error.to_string()))?;
        if !is_ok_status(response.status) {
            return Err((response.status, peer_detail(&response)));
        }
        serde_json::from_value(
            response
                .body
                .ok_or((502, "Peer response missing.".into()))?,
        )
        .map_err(|error| (502, error.to_string()))
    }

    pub(crate) async fn agent_instance_forwarded(
        &self,
        key: Option<String>,
        body: serde_json::Value,
    ) -> Result<serde_json::Value, (u16, String)> {
        let result = if let Some(agent_instance_key) = key {
            let request = serde_json::from_value(body).map_err(|error| (400, error.to_string()))?;
            serde_json::to_value(
                self.update_agent_instance_forwarded_impl(
                    &models::UpdateAgentInstancePathParams { agent_instance_key },
                    &request,
                )
                .await
                .map_err(|()| (500, "Agent update failed.".into()))?,
            )
        } else {
            let request = serde_json::from_value(body).map_err(|error| (400, error.to_string()))?;
            serde_json::to_value(
                self.create_agent_instance_forwarded_impl(&request)
                    .await
                    .map_err(|()| (500, "Agent creation failed.".into()))?,
            )
        };
        result.map_err(|error| (500, error.to_string()))
    }

    /// `POST /v2/agent-instances/search` — filter, sort and paginate agent
    /// instances from the S4 read model (mirrors `search_element_instances_impl`).
    async fn search_agent_instances_impl(
        &self,
        body: &Option<models::AgentInstanceSearchQuery>,
    ) -> Result<apis::agent_instance::SearchAgentInstancesResponse, ()> {
        use apis::agent_instance::SearchAgentInstancesResponse as Resp;

        let filter = body.as_ref().and_then(|q| q.filter.as_ref());
        let rows = self.store.try_agent_instances().map_err(|_| ())?;
        let mut matched: Vec<&readstore::AgentInstanceRow> = rows
            .iter()
            .filter(|row| match filter {
                None => true,
                Some(f) => match_agent_instance_filter(row, f),
            })
            .collect();

        let sort = query::sort_keys(
            body.as_ref().and_then(|q| q.sort.as_ref()),
            |r: &models::AgentInstanceSearchQuerySortRequest| (r.field.clone(), r.order),
        );
        query::sort_items(
            &mut matched,
            &sort,
            |row, field| agent_instance_sort_val(row, field),
            |row| row.agent_instance_key,
        );

        let sorted: Vec<(u64, &readstore::AgentInstanceRow)> = matched
            .into_iter()
            .map(|row| (row.agent_instance_key, row))
            .collect();
        let page = query::paginate(sorted, body.as_ref().and_then(|q| q.page.as_ref()));
        let items: Vec<models::AgentInstanceResult> = page
            .items
            .into_iter()
            .map(agent_instance_result)
            .collect::<Result<_, _>>()
            .map_err(|_| ())?;

        Ok(Resp::Status200_TheAgentInstanceSearchResult(
            models::AgentInstanceSearchQueryResult::new(page.response, items),
        ))
    }

    /// `POST /v2/agent-instances/{agentInstanceKey}/history/search` — search an
    /// agent instance's conversation history from the S4 read model, defaulting to
    /// COMMITTED-only turns (the default lives in [`readstore::AgentHistoryFilter`]).
    async fn search_agent_instance_history_impl(
        &self,
        path_params: &models::SearchAgentInstanceHistoryPathParams,
        body: &Option<models::AgentInstanceHistorySearchQuery>,
    ) -> Result<apis::agent_instance::SearchAgentInstanceHistoryResponse, ()> {
        use apis::agent_instance::SearchAgentInstanceHistoryResponse as Resp;

        let key: Key = match path_params.agent_instance_key.parse() {
            Ok(k) if k > 0 => k,
            _ => {
                return Ok(Resp::Status400_TheProvidedDataIsNotValid(problem(
                    "Invalid agent instance key",
                    400,
                    format!(
                        "Agent instance key '{}' is not a valid key.",
                        path_params.agent_instance_key
                    ),
                )));
            }
        };

        let filter = body.as_ref().and_then(|q| q.filter.as_ref());
        let commit_status = filter
            .and_then(|filter| filter.commit_status.as_ref())
            .map(agent_commit_status_filter_values);
        let history_filter = readstore::AgentHistoryFilter {
            agent_instance_key: Some(key),
            process_instance_key: None,
            commit_status,
            ..Default::default()
        };
        // An explicit empty inclusion set (`commitStatus: { $in: [] }`) matches
        // nothing. The read-model collapses `Some(vec![])` to the COMMITTED-only
        // default (see `AgentHistoryFilter`), so honour "match nothing" here by
        // skipping the query rather than silently returning committed rows.
        let rows = if matches!(&history_filter.commit_status, Some(v) if v.is_empty()) {
            Vec::new()
        } else {
            self.store
                .try_agent_history(&history_filter)
                .map_err(|_| ())?
        };

        let mut matched: Vec<&readstore::AgentHistoryRow> = rows
            .iter()
            .filter(|row| match filter {
                None => true,
                Some(f) => {
                    query::match_agent_history_item_key(
                        &f.history_item_key,
                        &row.agent_history_key.to_string(),
                    ) && query::match_element_instance_key(
                        &f.element_instance_key,
                        &row.element_instance_key.to_string(),
                    ) && query::match_job_key(&f.job_key, &row.job_key.to_string())
                        && f.loop_iteration.as_ref().is_none_or(|lf| {
                            query::match_integer(&Some(lf.clone()), Some(row.loop_iteration as i64))
                        })
                        && f.role
                            .as_ref()
                            .is_none_or(|rf| match_agent_history_role(rf, row.role))
                        && query::match_date_time_ms(
                            &f.produced_at,
                            Some(row.produced_at_ms as i64),
                        )
                }
            })
            .collect();

        let sort = query::sort_keys(
            body.as_ref().and_then(|q| q.sort.as_ref()),
            |r: &models::AgentInstanceHistorySearchQuerySortRequest| (r.field.clone(), r.order),
        );
        query::sort_items(
            &mut matched,
            &sort,
            |row, field| agent_history_sort_val(row, field),
            |row| row.agent_history_key,
        );

        let sorted: Vec<(u64, &readstore::AgentHistoryRow)> = matched
            .into_iter()
            .map(|row| (row.agent_history_key, row))
            .collect();
        let page = query::paginate(sorted, body.as_ref().and_then(|q| q.page.as_ref()));
        let items: Vec<models::AgentInstanceHistoryItemResult> = page
            .items
            .into_iter()
            .map(agent_history_item_result)
            .collect::<Result<_, _>>()
            .map_err(|_| ())?;

        Ok(Resp::Status200_TheAgentInstanceHistorySearchResult(
            models::AgentInstanceHistorySearchQueryResult::new(page.response, items),
        ))
    }

    async fn search_user_tasks_impl(
        &self,
        body: &Option<models::UserTaskSearchQuery>,
    ) -> Result<apis::user_task::SearchUserTasksResponse, ()> {
        use apis::user_task::SearchUserTasksResponse as Resp;

        let filter = body.as_ref().and_then(|q| q.filter.as_ref());
        let tasks = self.store.user_tasks();

        let mut matched: Vec<&readstore::UserTaskRow> = tasks
            .iter()
            .filter(|task| filter.is_none_or(|f| match_user_task_filter(task, f)))
            .collect();

        let sort = query::sort_keys(
            body.as_ref().and_then(|q| q.sort.as_ref()),
            |r: &models::UserTaskSearchQuerySortRequest| (r.field.clone(), r.order),
        );
        query::sort_items(
            &mut matched,
            &sort,
            |task, field| match field {
                "processInstanceKey" => query::SortVal::Num(task.instance_key as i64),
                "elementId" => query::SortVal::Str(task.element_id.clone()),
                "state" => query::SortVal::Str(user_task_state_enum(task.state).to_string()),
                "creationDate" => query::SortVal::Num(task.created_at_ms as i64),
                "businessId" => query::SortVal::Str(task.business_id.clone().unwrap_or_default()),
                _ => query::SortVal::Num(task.key as i64),
            },
            |task| task.key,
        );

        let sorted: Vec<(u64, &readstore::UserTaskRow)> =
            matched.into_iter().map(|task| (task.key, task)).collect();
        let page = query::paginate(sorted, body.as_ref().and_then(|q| q.page.as_ref()));
        // One resolver spans the whole page so tasks sharing a parent chain walk
        // it once (mirrors the process-instance search; issue #1095).
        let roots = readstore::RootResolver::new(|k| self.store.process_instance(k));
        let items: Vec<models::UserTaskResult> = page
            .items
            .into_iter()
            .map(|task| user_task_result(task, &roots))
            .collect();

        Ok(Resp::Status200_TheUserTaskSearchResult(
            models::UserTaskSearchQueryResult::new(page.response, items),
        ))
    }

    async fn assign_user_task_impl(
        &self,
        path_params: &models::AssignUserTaskPathParams,
        body: &models::UserTaskAssignmentRequest,
    ) -> Result<apis::user_task::AssignUserTaskResponse, ()> {
        use apis::user_task::AssignUserTaskResponse as Resp;

        let user_task_key: u64 = match path_params.user_task_key.parse() {
            Ok(k) => k,
            Err(_) => {
                return Ok(Resp::Status404_TheUserTaskWithTheGivenKeyWasNotFound(
                    problem(
                        "User task not found",
                        404,
                        format!(
                            "User task key '{}' is not a valid key.",
                            path_params.user_task_key
                        ),
                    ),
                ));
            }
        };

        let assignee = body.assignee.clone().unwrap_or_default();
        // Per the v2 contract, assignment overrides an existing assignee unless
        // the caller explicitly opts out with allowOverride = false.
        let allow_override = match &body.allow_override {
            Some(types::Nullable::Present(v)) => *v,
            _ => true,
        };
        if let Some(node) = self.route_by_leader(user_task_key) {
            let payload = serde_json::to_value(body).ok();
            let (status, detail) = self
                .forward_user_task(
                    node,
                    crate::falcon::UserTaskOp::Assign,
                    user_task_key,
                    payload,
                )
                .await;
            return Ok(match status {
                204 => Resp::Status204_TheUserTask,
                404 => Resp::Status404_TheUserTaskWithTheGivenKeyWasNotFound(problem(
                    "User task not found",
                    404,
                    detail,
                )),
                409 => Resp::Status409_TheUserTaskWithTheGivenKeyIsInTheWrongStateCurrently(
                    problem("User task in wrong state", 409, detail),
                ),
                503 => Resp::Status503_TheServiceIsCurrentlyUnavailable(problem(
                    "Service unavailable",
                    503,
                    detail,
                )),
                s => Resp::Status500_AnInternalErrorOccurredWhileProcessingTheRequest(problem(
                    "Peer error",
                    500,
                    if detail.is_empty() {
                        format!("peer node {node} returned status {s}")
                    } else {
                        detail
                    },
                )),
            });
        }
        let command = Command::AssignUserTask {
            user_task_key,
            assignee,
            allow_override,
        };
        match self.apply_partition_command(user_task_key, command).await {
            Ok(_) => Ok(Resp::Status204_TheUserTask),
            Err((404, detail)) => Ok(Resp::Status404_TheUserTaskWithTheGivenKeyWasNotFound(
                problem("User task not found", 404, detail),
            )),
            Err((409, detail)) => Ok(
                Resp::Status409_TheUserTaskWithTheGivenKeyIsInTheWrongStateCurrently(problem(
                    "User task in wrong state",
                    409,
                    detail,
                )),
            ),
            Err((503, detail)) => Ok(Resp::Status503_TheServiceIsCurrentlyUnavailable(problem(
                "Service unavailable",
                503,
                detail,
            ))),
            Err((_, detail)) => Ok(
                Resp::Status500_AnInternalErrorOccurredWhileProcessingTheRequest(problem(
                    "Internal error",
                    500,
                    detail,
                )),
            ),
        }
    }

    async fn complete_user_task_impl(
        &self,
        path_params: &models::CompleteUserTaskPathParams,
        body: &Option<models::UserTaskCompletionRequest>,
    ) -> Result<apis::user_task::CompleteUserTaskResponse, ()> {
        use apis::user_task::CompleteUserTaskResponse as Resp;

        let user_task_key: u64 = match path_params.user_task_key.parse() {
            Ok(k) => k,
            Err(_) => {
                return Ok(Resp::Status404_TheUserTaskWithTheGivenKeyWasNotFound(
                    problem(
                        "User task not found",
                        404,
                        format!(
                            "User task key '{}' is not a valid key.",
                            path_params.user_task_key
                        ),
                    ),
                ));
            }
        };

        // Variables the human submits are merged into the instance so they can
        // drive downstream gateway routing.
        if let Some(node) = self.route_by_leader(user_task_key) {
            let payload = serde_json::to_value(body).ok();
            let (status, detail) = self
                .forward_user_task(
                    node,
                    crate::falcon::UserTaskOp::Complete,
                    user_task_key,
                    payload,
                )
                .await;
            return Ok(match status {
                204 => Resp::Status204_TheUserTaskWasCompletedSuccessfully,
                404 => Resp::Status404_TheUserTaskWithTheGivenKeyWasNotFound(problem(
                    "User task not found",
                    404,
                    detail,
                )),
                409 => Resp::Status409_TheUserTaskWithTheGivenKeyIsInTheWrongStateCurrently(
                    problem("User task in wrong state", 409, detail),
                ),
                503 => Resp::Status503_TheServiceIsCurrentlyUnavailable(problem(
                    "Service unavailable",
                    503,
                    detail,
                )),
                s => Resp::Status500_AnInternalErrorOccurredWhileProcessingTheRequest(problem(
                    "Peer error",
                    500,
                    if detail.is_empty() {
                        format!("peer node {node} returned status {s}")
                    } else {
                        detail
                    },
                )),
            });
        }
        let variables = body
            .as_ref()
            .and_then(|b| b.variables.as_ref())
            .and_then(|v| match v {
                types::Nullable::Present(map) => Some(from_object_map(map)),
                types::Nullable::Null => None,
            })
            .unwrap_or_default();

        let command = Command::complete_user_task_with(user_task_key, variables);
        match self.apply_partition_command(user_task_key, command).await {
            Ok(_) => {
                // Completing a user task advances the token, which may create a
                // following job: wake any long-pollers.
                self.signal_jobs_available();
                Ok(Resp::Status204_TheUserTaskWasCompletedSuccessfully)
            }
            Err((404, detail)) => Ok(Resp::Status404_TheUserTaskWithTheGivenKeyWasNotFound(
                problem("User task not found", 404, detail),
            )),
            Err((409, detail)) => Ok(
                Resp::Status409_TheUserTaskWithTheGivenKeyIsInTheWrongStateCurrently(problem(
                    "User task in wrong state",
                    409,
                    detail,
                )),
            ),
            Err((503, detail)) => Ok(Resp::Status503_TheServiceIsCurrentlyUnavailable(problem(
                "Service unavailable",
                503,
                detail,
            ))),
            Err((_, detail)) => Ok(
                Resp::Status500_AnInternalErrorOccurredWhileProcessingTheRequest(problem(
                    "Internal error",
                    500,
                    detail,
                )),
            ),
        }
    }

    /// Returns a single user task from the read model by key.
    async fn get_user_task_impl(
        &self,
        path_params: &models::GetUserTaskPathParams,
    ) -> Result<apis::user_task::GetUserTaskResponse, ()> {
        use apis::user_task::GetUserTaskResponse as Resp;

        let user_task_key: u64 = match path_params.user_task_key.parse() {
            Ok(k) => k,
            Err(_) => {
                return Ok(Resp::Status404_TheUserTaskWithTheGivenKeyWasNotFound(
                    problem(
                        "User task not found",
                        404,
                        format!(
                            "User task key '{}' is not a valid key.",
                            path_params.user_task_key
                        ),
                    ),
                ));
            }
        };

        match self
            .store
            .user_tasks()
            .iter()
            .find(|t| t.key == user_task_key)
        {
            Some(task) => Ok(Resp::Status200_TheUserTaskIsSuccessfullyReturned(
                user_task_result(
                    task,
                    &readstore::RootResolver::new(|k| self.store.process_instance(k)),
                ),
            )),
            None => {
                if let Some(node) = self.read_route(user_task_key) {
                    let (status, body) = self
                        .forward_get(node, crate::falcon::ReadKind::UserTask, user_task_key)
                        .await;
                    return Ok(match (status, body) {
                        (200, Some(b)) => match serde_json::from_value(b) {
                            Ok(r) => Resp::Status200_TheUserTaskIsSuccessfullyReturned(r),
                            Err(e) => {
                                Resp::Status500_AnInternalErrorOccurredWhileProcessingTheRequest(
                                    problem("Peer error", 500, e.to_string()),
                                )
                            }
                        },
                        (404, _) => Resp::Status404_TheUserTaskWithTheGivenKeyWasNotFound(problem(
                            "User task not found",
                            404,
                            format!("No user task with key {user_task_key}."),
                        )),
                        (s, _) => Resp::Status500_AnInternalErrorOccurredWhileProcessingTheRequest(
                            problem(
                                "Peer error",
                                500,
                                format!("peer node {node} returned status {s}"),
                            ),
                        ),
                    });
                }
                Ok(Resp::Status404_TheUserTaskWithTheGivenKeyWasNotFound(
                    problem(
                        "User task not found",
                        404,
                        format!("No user task with key {user_task_key}."),
                    ),
                ))
            }
        }
    }

    /// The form linked to a user task (Camunda `GetUserTaskForm`). Resolves the
    /// task's `form_key` (set at creation from its `zeebe:formDefinition formId`)
    /// to the deployed form. Returns 204 when the task exists but declares no
    /// form, and 404 when no such task exists.
    async fn get_user_task_form_impl(
        &self,
        path_params: &models::GetUserTaskFormPathParams,
    ) -> Result<apis::user_task::GetUserTaskFormResponse, ()> {
        use apis::user_task::GetUserTaskFormResponse as Resp;

        let user_task_key: u64 = match path_params.user_task_key.parse() {
            Ok(k) => k,
            Err(_) => {
                return Ok(Resp::Status404_NotFound(problem(
                    "User task not found",
                    404,
                    format!(
                        "User task key '{}' is not a valid key.",
                        path_params.user_task_key
                    ),
                )));
            }
        };

        // Resolve the task's form key: locally first, then from the owning node
        // for a task on a remote partition (forms are replicated to every node,
        // so the form itself is always resolvable locally once we know its key).
        let form_key: Option<u64> = match self.store.user_task(user_task_key) {
            Some(task) => task.form_key,
            None => {
                if let Some(node) = self.read_route(user_task_key) {
                    let (status, body) = self
                        .forward_get(node, crate::falcon::ReadKind::UserTask, user_task_key)
                        .await;
                    match (status, body) {
                        (200, Some(b)) => match serde_json::from_value::<models::UserTaskResult>(b)
                        {
                            Ok(r) => match r.form_key {
                                types::Nullable::Present(fk) => match fk.0.parse::<u64>() {
                                    Ok(k) => Some(k),
                                    // A peer that reports a non-numeric form key
                                    // is corrupted or schema-incompatible;
                                    // surface it as a 500 rather than silently
                                    // masking it as "found, no form" (204).
                                    Err(_) => {
                                        return Ok(
                                            Resp::Status500_AnInternalErrorOccurredWhileProcessingTheRequest(
                                                problem(
                                                    "Peer error",
                                                    500,
                                                    format!(
                                                        "peer node {node} returned a non-numeric form key '{}'",
                                                        fk.0
                                                    ),
                                                ),
                                            ),
                                        );
                                    }
                                },
                                types::Nullable::Null => None,
                            },
                            Err(e) => {
                                return Ok(
                                    Resp::Status500_AnInternalErrorOccurredWhileProcessingTheRequest(
                                        problem("Peer error", 500, e.to_string()),
                                    ),
                                );
                            }
                        },
                        (404, _) => {
                            return Ok(Resp::Status404_NotFound(problem(
                                "User task not found",
                                404,
                                format!("No user task with key {user_task_key}."),
                            )));
                        }
                        (s, _) => {
                            return Ok(
                                Resp::Status500_AnInternalErrorOccurredWhileProcessingTheRequest(
                                    problem(
                                        "Peer error",
                                        500,
                                        format!("peer node {node} returned status {s}"),
                                    ),
                                ),
                            );
                        }
                    }
                } else {
                    return Ok(Resp::Status404_NotFound(problem(
                        "User task not found",
                        404,
                        format!("No user task with key {user_task_key}."),
                    )));
                }
            }
        };

        match form_key {
            Some(fk) => match self.store.form_by_key(fk) {
                Some(row) => Ok(Resp::Status200_TheFormIsSuccessfullyReturned(form_result(
                    &row,
                ))),
                // The task references a form key that is not (yet) projected:
                // treat as "found, no form" rather than a hard error.
                None => Ok(Resp::Status204_TheUserTaskWasFound),
            },
            None => Ok(Resp::Status204_TheUserTaskWasFound),
        }
    }

    /// The start form linked to a process definition (Camunda
    /// `GetStartProcessForm`). Resolves the definition's `start_form_id` (its
    /// start event's `zeebe:formDefinition formId`) to the latest deployed form.
    /// Returns 204 when the process exists but declares no start form, and 404
    /// when no such process definition exists.
    async fn get_start_process_form_impl(
        &self,
        path_params: &models::GetStartProcessFormPathParams,
    ) -> Result<apis::process_definition::GetStartProcessFormResponse, ()> {
        use apis::process_definition::GetStartProcessFormResponse as Resp;

        let key: u64 = match path_params.process_definition_key.parse() {
            Ok(k) => k,
            Err(_) => {
                return Ok(Resp::Status404_NotFound(problem(
                    "Process definition not found",
                    404,
                    format!(
                        "Process definition key '{}' is not a valid key.",
                        path_params.process_definition_key
                    ),
                )));
            }
        };

        // Process definitions are replicated to every node, so a local lookup is
        // authoritative. `None` => no such definition; `Some(None)` => the
        // definition exists but declares no start form.
        match self.store.process_definition_start_form_id(key) {
            None => Ok(Resp::Status404_NotFound(problem(
                "Process definition not found",
                404,
                format!("No process definition with key {key}."),
            ))),
            Some(None) => Ok(Resp::Status204_TheProcessWasFound),
            Some(Some(form_id)) => match self.store.form_by_id(&form_id) {
                Some(row) => Ok(Resp::Status200_TheFormIsSuccessfullyReturned(form_result(
                    &row,
                ))),
                // The start form id is declared but no such form is deployed:
                // treat as "found, no form".
                None => Ok(Resp::Status204_TheProcessWasFound),
            },
        }
    }

